window.HS_LOAD(4,{"intro":[[["نبی کریمؐ اور آپؐ کے صحابہ کرامؓ کو ",""],["ٱللَّٰه","a"],[" کے ذکر کا کتنا شوق تھا اور وہ کس طرح صبح اور شام، دن رات، سفر اور حضر میں ذکر کی پابندی کرتے تھے اور وہ کس طرح دوسروں کو اس کی ترغیب دیتے تھے اور اس کا شوق دلاتے تھے اور ان کے اذکار کیسے تھے؟",""]]],"topics":{"95":{"lead":[],"stories":[{"b":[["n",[["حضرت ثوبانؓ","b"],[" فرماتے ہیں ہم ایک سفر میں حضورؐ کے ساتھ جا رہے تھے اتنے میں مہاجرین نے کہا جب سونے اور چاندی کے بارے میں قرآن نازل ہو چکا (جس میں بتایا گیا کہ جو لوگ مال و دولت اکٹھی کریں اور زکوٰۃ وغیرہ نہ دیں ",""],["ٱللَّٰه","a"],[" کے راستہ میں خرچ نہ کریں انہیں دردناک عذاب ہوگا) تو اب ہمیں کس طرح پتہ چل جائے کہ کونسا مال بہتر ہے؟ اس پر حضرت عمرؓ نے فرمایا اگر کہو تو میں آپ لوگوں کو یہ بات حضورؐ سے پوچھ دوں؟ انہوں نے کہا ضرور۔ حضرت عمرؓ حضورؐ کی طرف چل دیے۔ میں بھی اپنے اونٹ کو تیز دوڑاتا ہوا ان کے پیچھے چل پڑا۔ حضرت عمرؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ابھی سونے اور چاندی کے بارے میں قرآن کی آیتیں نازل ہوئی ہیں اس پر مہاجرین کہہ رہے ہیں کہ جب سونے اور چاندی کے بارے میں قرآن نازل ہو چکا تو اب ہمیں کس طرح پتہ چل جائے کہ کون سا مال بہتر ہے؟ حضورؐ نے فرمایا تم اپنی زبان کو ذکر کرنے والا اور دل کو شکر کرنے والا بنا لو اور ایسی مومن عورت سے شادی کرو جو ایمان (والے کاموں) میں تمہاری مدد کرے۔ دوسری روایت میں یہ ہے کہ وہ آخرت (والے کاموں) میں تمہاری مدد کرے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ کا فرمان ہے",""]]],["q",[["وَٱلَّذِينَ يَكْنِزُونَ ٱلذَّهَبَ وَٱلْفِضَّةَ وَلَا يُنفِقُونَهَا فِى سَبِيلِ ٱللَّهِ فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ  (سورۃ توبہ: ۳۴)","a"]]],["p",[["ترجمہ: \"جو لوگ سونا چاندی جمع کر رکھتے ہیں اور ان کو ",""],["ٱللَّٰه","a"],[" کی راہ میں خرچ نہیں کرتے سو آپ ان کو ایک بڑی دردناک سزا کی خبر سنا دیجیے۔\" اس کے بارے میں حضرت علیؓ نے فرمایا کہ نبی کریمؐ نے تین مرتبہ ارشاد فرمایا ہلاکت ہو سونے کے لیے، ہلاکت ہو چاندی کے لیے۔ یہ فرمان حضورؐ کے صحابہؓ پر بڑا گراں گزرا اور انہوں نے عرض کیا اب ہم کس چیز کو مال بنا کر اپنے پاس رکھیں؟ اس پر حضرت عمرؓ نے فرمایا (میں پوچھ کر آتا ہوں)۔ آگے پچھلی حدیث سے مختصر حدیث ذکر کی ہے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Abu Nu'aym in his Hilya (Vol.1 Pg.182). Ahmad, Tirmidhi and Ibn Maajah have reported a similar narration."],["(2)","Abdur Razzaaq, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.351)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ مکہ کے راستہ میں تشریف لے جا رہے تھے۔ آپؐ کا گزر ایک پہاڑ کے پاس سے ہوا جسے جمدان کہا جاتا ہے۔ آپؐ نے فرمایا چلتے رہو یہ جمدان ہے مفردون آگے نکل گئے۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مفردون کون لوگ ہیں؟ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کا بہت زیادہ ذکر کرنے والے مرد اور عورتیں۔",""],[" (3)","s"]]]],"f":[["(3)","Muslim."]]},{"b":[["n",[["ترمذی میں ہے کہ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مفردون کون لوگ ہیں؟ آپؐ نے فرمایا جو لوگ ",""],["ٱللَّٰه","a"],[" کے ذکر پر فریفتہ ہوں اور ذکر ان کے سارے بوجھ اتار دے گا اور وہ قیامت کے دن بالکل ہلکے پھلکے ہو کر ",""],["ٱللَّٰه","a"],[" کے سامنے حاضر ہوں گے۔",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.59). Tabraani has reported a similar narration from Hadhrat Abu Dardaa, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.75)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ ہم لوگ حضورؐ کے ساتھ جا رہے تھے کہ اتنے میں آپؐ نے ارشاد فرمایا کہاں ہیں آگے نکل جانے والے؟ صحابہؓ نے عرض کیا کچھ لوگ آگے جا چکے ہیں اور کچھ لوگ پیچھے رہ گئے ہیں۔ حضورؐ نے فرمایا (سفر میں آگے نکل جانا مراد نہیں ہے بلکہ) وہ آگے نکل جانے والے کہاں ہیں جو ",""],["ٱللَّٰه","a"],[" کے ذکر پر فریفتہ ہوں؟ جو جنت کے باغوں میں چرنا چاہتا ہے اسے چاہیے کہ وہ ",""],["ٱللَّٰه","a"],[" کا ذکر زیادہ کرے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.10 Pg.75) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے حضورؐ سے پوچھا کہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" کے نزدیک کون سے بندے سب سے افضل درجہ والے ہوں گے؟ آپؐ نے فرمایا جو ",""],["ٱللَّٰه","a"],[" کا بہت زیادہ ذکر کرنے والے ہوں گے۔ حضرت ابوسعیدؓ فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" کے راستہ میں غزوہ کرنے والوں سے بھی زیادہ افضل ہوں گے؟ آپؐ نے فرمایا ہاں۔ اگر غازی اپنی تلوار کفار اور مشرکین پر اتنی زیادہ چلائے کہ وہ ٹوٹ جائے اور وہ خود خون میں رنگا جائے تو بھی ",""],["ٱللَّٰه","a"],[" کا بہت زیادہ ذکر کرنے والے اس سے درجے میں افضل ہوں گے۔",""],[" (6)","s"]]]],"f":[["(6)","Tirmidhi and Bayhaqi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.56)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں نبی کریمؐ نے فرمایا کسی آدمی نے کوئی عمل ایسا نہیں کیا جو ",""],["ٱللَّٰه","a"],[" کے ذکر سے زیادہ عذاب سے نجات دینے والا ہو۔ کسی نے عرض کیا کہ کیا ",""],["ٱللَّٰه","a"],[" کے راستہ میں جہاد بھی ",""],["ٱللَّٰه","a"],[" کے ذکر سے زیادہ نجات دینے والا نہیں؟ آپؐ نے فرمایا نہیں سوائے اس کے کہ مجاہد اپنی تلوار اتنی چلائے کہ وہ ٹوٹ جائے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Sagheer and Awsat, reporting from reliable sources as confirmed by Mundhiri (Vol.3 Pg.56) and Haythami (Vol.10 Pg.74). Tabraani has reported a similar narration from Hadhrat Mu'aadh bin Jabal, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.73)."]]},{"b":[["n",[["حضرت معاذ بن انسؓ","b"],[" فرماتے ہیں کہ حضورؐ سے ایک آدمی نے پوچھا کون سا مجاہد سب سے زیادہ اجر والا ہے؟ آپؐ نے فرمایا جو ان میں ",""],["ٱللَّٰه","a"],[" کا سب سے زیادہ ذکر کرنے والا ہے۔ پھر اس نے پوچھا کون سا نیک بندہ سب سے زیادہ اجر والا ہے؟ آپؐ نے فرمایا جو ",""],["ٱللَّٰه","a"],[" کا سب سے زیادہ ذکر کرنے والا ہے۔ پھر اس نے نماز، زکوٰۃ، حج اور صدقہ میں سے ہر ایک عمل کا ذکر کیا۔ حضورؐ ہر ایک کے جواب میں یہی فرماتے رہے کہ جو ",""],["ٱللَّٰه","a"],[" کا سب سے زیادہ ذکر کرنے والا ہے۔ اس پر حضرت ابوبکرؓ نے حضرت عمرؓ سے فرمایا اے ابوحفص! ذکر والے تو ساری خیر لے گئے۔ حضورؐ نے فرمایا بالکل۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad. A narration of Tabraani states that the Sahabi asked, \"Which Mujaahid shall receive the most reward?\" Haythami (Vol.10 Pg.74) has however commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن بسرؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے عرض کیا کہ اسلام کے نفلی اعمال بہت زیادہ ہیں آپؐ مجھے کوئی ایسا عمل بتائیں جسے میں مضبوطی سے پکڑ لوں۔ آپؐ نے فرمایا تمہاری زبان ہر وقت ",""],["ٱللَّٰه","a"],[" کے ذکر سے تر رہے۔",""],[" (9)","s"]]]],"f":[["(9)","Tirmidhi, Haakim, Ibn Maajah and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.54)."]]},{"b":[["n",[["حضرت مالک بن یخامرؒ","b"],[" کہتے ہیں کہ حضرت معاذ بن جبلؓ نے اپنے ساتھیوں سے فرمایا حضورؐ سے جدائی کے وقت میری جو آخری گفتگو حضورؐ سے ہوئی وہ یہ تھی کہ میں نے عرض کیا کونسا عمل ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ محبوب ہے؟ آپؐ نے فرمایا تمہاری موت اس حال میں آئے کہ تمہاری زبان ",""],["ٱللَّٰه","a"],[" کے ذکر سے تر ہو۔ بزار کی روایت میں ہے کہ مجھے سب سے افضل اور ",""],["ٱللَّٰه","a"],[" کے سب سے زیادہ قریب عمل بتائیں۔",""],[" (10)","s"],[" (11)","s"]]]],"f":[["(10)","Tabraani. Haythami (Vol.10 Pg.74) has commented on the chain of narrators."],["(11)","Bazzaar. Ibn Abi Dunya and Ibn Hibbaan have reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.55). Ibn Najjaar has also reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.208)."]]}]},"96":{"lead":[],"stories":[{"b":[["n",[["حضرت عمرؓ","b"],[" نے فرمایا اپنے آپ کو انسانوں کے تذکرے میں مشغول نہ کرو کیونکہ یہ تو بلاء اور مصیبت ہے بلکہ ",""],["ٱللَّٰه","a"],[" کا ذکر اہتمام سے کرو۔ حضرت عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کا ذکر پابندی سے کرو کیونکہ یہ تو سراسر شفاء ہے اور انسانوں کے تذکرے سے بچو کیونکہ یہ سراسر بیماری ہے۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Ibn Abi Dunya."],["(2)","Ibn Abi Dunya, Ahmad and Hannaad, as quoted in Kanzul Ummaal (Vol.1 Pg.207)."]]},{"b":[["n",[["حضرت عثمانؓ","b"],[" نے فرمایا اگر ہمارے دل پاک ہوتے تو ",""],["ٱللَّٰه","a"],[" کے ذکر سے کبھی نہ اکتاتے۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Mubaarak in his Zuhd, as quoted in Kanzul Ummaal (Vol.1 Pg.218)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ کا ذکر کثرت سے کرو اور اس میں بھی کوئی حرج نہیں ہے کہ تم صرف ایسے آدمی کے ساتھ رہو جو ",""],["ٱللَّٰه","a"],[" کے ذکر میں تمہاری مدد کرے (اصل یہ ہے کہ انسان اصول و آداب کے ساتھ سب سے مل جل کر رہے اور یہی افضل ہے اور جو صبر نہ کر سکے تو مجبوری کی وجہ سے الگ تھلگ رہا کرے)۔",""],[" (4)","s"]]]],"f":[["(4)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.208)."]]},{"b":[["n",[["حضرت سلمانؓ","b"],[" نے فرمایا اگر ایک آدمی رات بھر گوری چٹی باندیاں تقسیم کرتا رہے اور دوسرا آدمی رات بھر قرآن پڑھتا رہے اور ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہے تو یہ ذکر والا افضل ہوگا۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.204)."]]},{"b":[["n",[["حضرت حبیب بن عبیدؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت ابوالدرداءؓ کی خدمت میں حاضر ہو کر عرض کیا کہ مجھے کچھ وصیت فرما دیں۔ حضرت ابوالدرداءؓ نے فرمایا تم خوشی میں ",""],["ٱللَّٰه","a"],[" کو یاد رکھو ",""],["ٱللَّٰه","a"],[" تکلیف میں تمہیں یاد رکھے گا اور جب تمہارا دل دنیا کی کسی چیز کی طرف جھانکے تو تم اس میں غور کرو کہ اس کا انجام کیا ہوگا؟",""],[" (6)","s"]]]],"f":[["(6)","Ahmad, as quoted in Safwatus Safwah (Vol.1 Pg.258)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا کیا میں تمہیں وہ عمل نہ بتا دوں جو تمہارے اعمال میں سب سے بہتر ہے، تمہارے مالک یعنی ",""],["ٱللَّٰه","a"],[" تعالیٰ کو سب سے زیادہ محبوب ہے، تمہارے درجات کو سب سے زیادہ بڑھانے والا ہے اور اس سے بھی بہتر ہے کہ تم دشمن کی لڑائی کرو اور وہ تم کو قتل کریں اور تم ان کو قتل کرو اور درہم و دینار تقسیم کرنے سے بھی بہتر؟ لوگوں نے عرض کیا اے ابوالدرداء! وہ عمل کونسا ہے؟ فرمایا ",""],["ٱللَّٰه","a"],[" کا ذکر اور ",""],["ٱللَّٰه","a"],[" کا ذکر سب سے بڑی نیکی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilya (Vol.1 Pg.219)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا جن لوگوں کی زبانیں ہر وقت ",""],["ٱللَّٰه","a"],[" کے ذکر سے تر رہیں گی ان میں سے ہر آدمی جنت میں ہنستا ہوا داخل ہوگا۔",""],[" (8)","s"]]]],"f":[["(8)","Abu Nu'aym in his Hilya (Vol.1 Pg.219)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" نے فرمایا کسی آدمی نے کوئی عمل ایسا نہیں کیا جو ",""],["ٱللَّٰه","a"],[" کے ذکر سے زیادہ ",""],["ٱللَّٰه","a"],[" کے عذاب سے نجات دینے والا ہو۔ لوگوں نے عرض کیا اے ابوعبدالرحمٰن! کیا جہاد فی سبیل ",""],["ٱللَّٰه","a"],[" بھی اس سے زیادہ نجات دینے والا نہیں؟ فرمایا نہیں کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنی کتاب میں فرماتے ہیں",""]]],["q",[["وَلَذِكْرُ ٱللَّهِ أَكْبَرُ  (سورۃ عنکبوت: ۴۵)","a"]]],["p",[["ترجمہ: \"اور ",""],["ٱللَّٰه","a"],[" کی یاد بہت بڑی چیز ہے۔\" ہاں اگر مجاہد اتنی تلوار چلائے کہ وہ ٹوٹ جائے (تو یہ اس سے زیادہ نجات دینے والا ہے)۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.235)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں صبح اور شام ",""],["ٱللَّٰه","a"],[" کا ذکر کرنا ",""],["ٱللَّٰه","a"],[" کے راستہ میں تلواریں توڑ دینے سے اور مال لٹا دینے سے زیادہ افضل ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.207)."]]}]},"97":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا میں ایسی جماعت کے ساتھ بیٹھوں جو فجر کی نماز کے بعد سے لے کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہی ہو یہ مجھے اولاد اسماعیلؑ میں سے ایسے چار غلام آزاد کرنے سے زیادہ محبوب ہے جن میں سے ہر ایک کا خون بہا بارہ ہزار ہو اور میں ایسی جماعت کے ساتھ بیٹھوں جو عصر کی نماز کے بعد سے لے کر سورج غروب ہونے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتی رہے یہ مجھے اولاد اسماعیلؑ میں سے ایسے چار غلام آزاد کرنے سے زیادہ محبوب ہے جس میں سے ہر ایک کا خون بہا بارہ ہزار ہو۔ احمد و ابویعلیٰ حضرت انسؓ سے روایت کرتے ہیں کہ حضورؐ نے فرمایا جو عصر پڑھ کر بیٹھ جائے اور شام ہونے تک خیر کی باتوں کا املا کرائے یہ اس آدمی سے افضل ہے جو اولاد اسماعیلؑ میں سے آٹھ غلام آزاد کرے اور ابویعلیٰ کی دوسری روایت میں یہ ہے کہ حضورؐ نے فرمایا میں ایسے لوگوں کے ساتھ بیٹھوں جو صبح سے لے کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے رہیں یہ مجھے ان تمام چیزوں سے زیادہ محبوب ہے جن پر سورج نکلتا ہے۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Abu Ya'la. Haythami (Vol.10 Pg.105) has commented on the chain of narrators."],["(2)","Ahmad and Abu Ya'la."],["(3)","Abu Ya'la. Haythami (Vol.10 Pg.105) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت سہل بن سعد ساعدیؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا میں صبح کی نماز میں شریک ہو کر سورج نکلنے تک بیٹھ کر ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہوں یہ مجھے اس سے زیادہ محبوب ہے کہ میں سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کے راستہ میں (مجاہدوں کو) عمدہ گھوڑے دیتا رہوں۔",""],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Kabeer and Awsat, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.105)."]]},{"b":[["n",[["حضرت عباس بن عبدالمطلبؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا میں صبح کی نماز سے لے کر سورج نکلنے تک (",""],["ٱللَّٰه","a"],[" کے ذکر کے لیے) بیٹھا رہوں یہ مجھے اولاد اسماعیلؑ میں سے چار غلام آزاد کرنے سے زیادہ محبوب ہے۔ بزار اور طبرانی کی روایت میں ہے کہ حضورؐ نے فرمایا کہ میں صبح کی نماز پڑھ کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہوں یہ مجھے ",""],["ٱللَّٰه","a"],[" کے راستہ میں سورج نکلنے تک گھوڑا دوڑانے سے زیادہ محبوب ہے۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Bazzaar."],["(6)","Tabraani. Haythami (Vol.10 Pg.106) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا",""]]],["q",[["سُبْحَانَ ٱللَّهِ وَٱلْحَمْدُ لِلَّهِ وَلَا إِلَٰهَ إِلَّا ٱللَّهُ وَٱللَّهُ أَكْبَرُ کہنا مجھے ان تمام چیزوں سے زیادہ محبوب ہے جن پر سورج نکلتا ہے۔","a"],[" (7)","s"]]]],"f":[["(7)","Muslim and Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.84)."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا میں فجر کے بعد بیٹھ کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہوں اور ",""],["ٱللَّٰه","a"],[" اکبر اور الحمد للہ وسبحان ",""],["ٱللَّٰه","a"],[" و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہتا رہوں یہ مجھے اولاد اسماعیلؑ میں سے دو غلام آزاد کرنے سے زیادہ محبوب ہے اور عصر کے بعد سورج ڈوبنے تک یہ کلمات کہتا رہوں یہ مجھے اولاد اسماعیلؑ میں سے چار غلام آزاد کرنے سے زیادہ محبوب ہے اور ایک روایت میں یہ ہے کہ میں سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہوں ",""],["ٱللَّٰه","a"],[" اکبر و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و سبحان ",""],["ٱللَّٰه","a"],[" کہتا رہوں یہ مجھے اولاد اسماعیلؑ میں سے چار غلام آزاد کرنے سے زیادہ محبوب ہے اور عصر کی نماز سے لے کر سورج ڈوبنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرنا مجھے اولاد اسماعیلؑ میں سے اتنے اور اتنے غلام آزاد کرنے سے زیادہ محبوب ہے۔",""],[" (8)","s"],[" (9)","s"]]]],"f":[["(8)","Ahmad."],["(9)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.104)."]]}]},"98":{"lead":[],"stories":[{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ میں صبح سے لے کر شام تک سارا دن ",""],["ٱللَّٰه","a"],[" کا ذکر کرتا رہوں یہ مجھے اس سے زیادہ محبوب ہے کہ میں صبح سے لے کر شام تک سارا دن لوگوں کو سواری کے لیے عمدہ گھوڑے دیتا رہوں۔ ",""],["حضرت ابوعبیدہ بن عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؒ","b"],[" فرماتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ کو ",""],["ٱللَّٰه","a"],[" کے ذکر کے علاوہ کوئی اور بات کرنے سے بہت گرانی ہوتی تھی۔ طبرانی کی ایک روایت میں یہ ہے کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ صبح صادق سے لے کر فجر کی نماز تک کسی کو بات کرتے ہوئے سنتے تو اس سے ان کو بہت گرانی ہوتی۔ طبرانی کی دوسری روایت میں یہ ہے کہ ",""],["حضرت عطاءؒ","b"],[" کہتے ہیں حضرت ابن مسعودؓ باہر آئے تو دیکھا کہ فجر کے بعد کچھ لوگ باتیں کر رہے ہیں انھوں نے ان لوگوں کو بات کرنے سے منع کیا اور فرمایا تم لوگ یہاں نماز کے لیے آئے ہو اس لیے یا تو نماز پڑھو یا چپ رہو۔",""],[" (1)","s"],[" (2)","s"],[" (3)","s"]]]],"f":[["(1)","Tabraani. Haythami (Vol.10 Pg.75) has commented on the chain of narrators."],["(2)","Tabraani in his Kabeer. Haythami (Vol.2 Pg.219) has commented on the chain of narrators."],["(3)","Tabraani. Haythami (Vol.2 Pg.219) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا سو دفعہ ",""],["ٱللَّٰه","a"],[" اکبر کہنا مجھے سو دینار صدقہ کرنے سے زیادہ پسند ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.219)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" نے فرمایا صبح سے لے کر رات تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرنا مجھے اس سے زیادہ محبوب ہے کہ میں صبح سے لے کر رات تک ",""],["ٱللَّٰه","a"],[" کے راستہ میں (مجاہدوں کو) عمدہ گھوڑے سواری کے لیے دیتا رہوں۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.235)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں ہم لوگ ایک سفر میں حضرت ابوموسیٰؓ کے ساتھ چل رہے تھے انھوں نے لوگوں کو فصیح اور بلیغ باتیں کرتے ہوئے سنا تو فرمایا اے انس! مجھے ان لوگوں سے کیا تعلق؟ آؤ ہم اپنے رب کا ذکر کریں کیونکہ یہ لوگ تو اپنی زبان سے کھال ادھیڑ دیں گے۔ اس کے بعد آگے ویسی حدیث ذکر کی جیسی آخرت پر ایمان لانے کے باب میں گزر چکی ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.259)."]]},{"b":[["n",[["حضرت معاذ بن عبد","b"],["ٱللَّٰه","a"],[" بن رافعؒ","b"],[" کہتے ہیں میں ایک مجلس میں تھا جس میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ، حضرت عبد",""],["ٱللَّٰه","a"],[" بن جعفرؓ اور حضرت عبد",""],["ٱللَّٰه","a"],[" بن ابی عمیرہؓ بھی تھے۔ حضرت ابن ابی عمیرہؓ نے فرمایا میں نے حضرت معاذ بن جبلؓ کو فرماتے ہوئے سنا کہ وہ کلمے ایسے ہیں کہ ان میں سے ایک کلمہ عرش تک پہنچ کر ہی رکتا ہے اس سے پہلے اسے کوئی روکنے والا نہیں اور دوسرا زمین و آسمان کے درمیان کے خلا کو بھر دیتا ہے اور وہ ہیں ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" اور ",""],["ٱللَّٰه","a"],[" اکبر۔ حضرت ابن عمرؓ نے حضرت ابن ابی عمیرہؓ سے کہا کیا آپ نے خود ان کو یہ فرماتے ہوئے سنا؟ انھوں نے کہا جی ہاں۔ حضرت ابن عمرؓ اتنا روئے کہ آنسوؤں سے ان کی داڑھی تر ہو گئی (انہیں اس بات کا غم تھا کہ مجھے اب تک حضورؐ کی یہ بات معلوم کیوں نہیں تھی) پھر فرمایا ہمیں ان دونوں کلمات سے بہت تعلق اور محبت ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani. Mundhiri (Vol.3 Pg.94) and Haythami (Vol.10 Pg.82) have commented on the chain of narrators."]]},{"b":[["n",[["حضرت جریریؒ","b"],[" کہتے ہیں کہ حضرت انس بن مالکؓ نے ذات عرق مقام سے احرام باندھا اور پھر احرام کھولنے تک ہم نے انہیں ",""],["ٱللَّٰه","a"],[" کے ذکر کے علاوہ اور کوئی بات کرتے ہوئے نہیں سنا۔ احرام کھول کر مجھ سے فرمایا اے بھتیجے! احرام اس طرح ہوا کرتا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Sa'd (Vol.7 Pg.22)."]]}]},"99":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن فرمائیں گے عنقریب حشر والوں کو پتہ چل جائے گا کہ کرم والے کون ہیں؟ کسی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! کرم والے کون ہیں؟ حضورؐ نے فرمایا ذکر کی مجلسوں والے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Abu Ya'la, Ibn Hibbaan, Bayhaqi and others, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.63). Haythami (Vol.10 Pg.72) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں نبی کریمؐ نے نجد کی طرف ایک لشکر بھیجا یہ لشکر بہت سا مال غنیمت لے کر جلدی ہی واپس آ گیا۔ ایک آدمی جو اس لشکر کے ساتھ نہیں گیا تھا اس نے کہا ہم نے اس جیسا کوئی لشکر نہیں دیکھا جو اتنا زیادہ مال غنیمت لے کر اتنی جلدی لوٹ آیا ہو۔ حضورؐ نے فرمایا کیا میں تمہیں ایسے لوگ نہ بتا دوں جو ان سے زیادہ مال غنیمت لے کر ان سے بھی زیادہ جلدی واپس آ گئے ہیں؟ یہ وہ لوگ ہیں جو صبح کی نماز میں شریک ہوں پھر اپنی جگہوں میں بیٹھ کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے رہیں۔ یہ ہیں وہ لوگ جو ان سے زیادہ مال غنیمت لے کر ان سے بھی زیادہ جلدی واپس آ گئے ہیں۔ ایک روایت میں یہ ہے کہ یہ وہ لوگ ہیں جو صبح کی نماز پڑھیں پھر اپنی جگہوں میں بیٹھ کر سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے رہیں پھر دو رکعت نماز پڑھ کر اپنے گھر واپس جائیں یہ ہیں وہ لوگ جو ان سے زیادہ مال غنیمت لے کر ان سے زیادہ جلدی واپس آ گئے ہیں۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Zanjway and Tirmidhi, as quoted in Kanzul Ummaal (Vol.1 Pg.298). Bazzaar has reported a similar narration from Hadhrat Abu Hurayrah with slight additions. Haythami (Vol.10 Pg.107) has however commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن سہل بن حنیفؓ","b"],[" فرماتے ہیں حضورؐ اپنے ایک گھر میں تھے کہ آپؐ پر یہ آیت نازل ہوئی",""]]],["q",[["وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ يُرِيدُونَ وَجْهَهُۥ  (سورۃ کہف: ۲۸)","a"]]],["p",[["ترجمہ: \"اور آپ اپنے کو ان لوگوں کے ساتھ مقید رکھا کیجیے جو صبح و شام (یعنی علی الدوام) اپنے رب کی عبادت محض اس کی رضا جوئی کے لیے کرتے ہیں۔\" حضورؐ ان کو تلاش کرنے نکلے تو دیکھا کہ لوگ ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے ہیں اور ان میں سے کچھ لوگوں کے سر کے بال بکھرے ہوئے ہیں اور کچھ لوگوں کی کھالیں خشک ہیں اور کچھ لوگوں کے پاس صرف ایک ہی کپڑا ہے۔ آپؐ ان کے پاس بیٹھ گئے اور فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میری امت میں ایسے لوگ پیدا کیے جن کے پاس بیٹھنے کا مجھے حکم دیا۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.81)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں نبی کریمؐ کا حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ پر گزر ہوا وہ اپنے ساتھیوں میں بیان کر رہے تھے۔ حضورؐ نے فرمایا غور سے سنو تم لوگ ہی وہ جماعت ہو جن کے پاس بیٹھنے کا ",""],["ٱللَّٰه","a"],[" نے مجھے حکم دیا ہے پھر آپؐ نے یہ آیت پڑھی",""]]],["q",[["وَٱصْبِرْ نَفْسَكَ مَعَ ٱلَّذِينَ يَدْعُونَ رَبَّهُم بِٱلْغَدَوٰةِ وَٱلْعَشِىِّ  ...  وَكَانَ أَمْرُهُۥ فُرُطًا  (سورۃ کہف: ۲۸) غور سے سنو تم لوگ جتنے بیٹھے ہو اتنے ہی تمہارے ساتھ فرشتے بھی بیٹھے ہوئے ہیں۔ اگر تم سبحان اللہ کہو گے تو وہ بھی سبحان اللہ کہیں گے اور اگر تم الحمد للہ کہو تو وہ بھی الحمد للہ کہیں گے اگر تم اللہ اکبر کہو گے تو وہ بھی اللہ اکبر کہیں گے پھر (مجلس ختم ہو جانے پر) وہ فرشتے اللہ تعالیٰ کے پاس اوپر چلے جائیں گے، حالانکہ اللہ تعالیٰ ان سے زیادہ جانتے ہیں لیکن پھر بھی وہ عرض کریں گے اے ہمارے رب! تیرے بندے سبحان اللہ کہتے رہے تو ہم بھی سبحان اللہ کہتے رہے اور وہ اللہ اکبر کہتے رہے تو ہم بھی اللہ اکبر کہتے رہے اور وہ الحمد للہ کہتے رہے تو ہم بھی الحمد للہ کہتے رہے۔ پھر ہمارے رب فرمائیں گے اے میرے فرشتو! میں تمہیں اس بات پر گواہ بناتا ہوں کہ میں نے ان کی مغفرت کر دی ہے۔ وہ فرشتے عرض کریں گے کہ ان میں تو فلاں خطا کار بھی تھے۔ اللہ تعالیٰ فرمائیں گے یہ ایسے لوگ ہیں کہ ان کے ساتھ بیٹھنے والا بھی محروم نہیں رہتا۔","a"],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Sagheer. Haythami (Vol.10 Pg.76) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ثابت بنانیؒ","b"],[" کہتے ہیں حضرت سلمانؓ ایک جماعت میں بیٹھے ہوئے تھے جو ",""],["ٱللَّٰه","a"],[" تعالیٰ کا ذکر کر رہے تھے حضورؐ ان کے پاس سے گزرے تو انہوں نے ذکر کرنا چھوڑ دیا۔ حضورؐ نے فرمایا آپ لوگ کیا کر رہے تھے؟ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہے تھے۔ حضورؐ نے فرمایا ذکر کرتے رہو کیونکہ میں نے آپ لوگوں پر رحمت کو اترتے ہوئے دیکھا ہے، اس لیے میں نے چاہا کہ میں بھی آپ لوگوں کے ساتھ اس رحمت میں شامل ہو جاؤں پھر فرمایا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میری امت میں ایسے لوگ بنائے ہیں جن کے ساتھ بیٹھنے کا مجھے حکم دیا گیا ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.342)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ ہمارے پاس باہر تشریف لائے اور فرمایا اے لوگو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرشتوں کی بہت سی جماعتیں مقرر فرما رکھی ہیں جو کہ زمین پر ",""],["ٱللَّٰه","a"],[" کے ذکر کی مجلسوں میں اترتی ہیں اور ان کے پاس ٹھہرتی ہیں، لہٰذا جنت کے باغوں میں چرا کرو۔ صحابہؓ نے پوچھا جنت کے باغ کہاں ہیں؟ حضورؐ نے فرمایا ذکر کی مجلس (جنت کے باغ ہیں) صبح شام ",""],["ٱللَّٰه","a"],[" کا ذکر کیا کرو بلکہ اپنے آپ کو ہمیشہ ",""],["ٱللَّٰه","a"],[" کے ذکر میں مشغول رکھو جو یہ جاننا چاہتا ہے کہ ",""],["ٱللَّٰه","a"],[" کے ہاں اس کا کیا مرتبہ ہے تو اسے چاہیے کہ وہ یہ دیکھ لے کہ اس کے نزدیک ",""],["ٱللَّٰه","a"],[" کا کیا مرتبہ ہے؟ کیونکہ بندہ ",""],["ٱللَّٰه","a"],[" کو اپنے نزدیک جو درجہ دیتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ بھی اپنے ہاں اس بندے کو وہی درجہ دیتے ہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Dunya, Abu Ya'la, Bazzaar, Tabraani, Haakim and Bayhaqi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.65). Haythami (Vol.10 Pg.77) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت جابر بن سمرہؓ","b"],[" فرماتے ہیں نبی کریمؐ جب صبح کی نماز پڑھ لیتے تو بیٹھ جاتے اور سورج نکلنے تک ",""],["ٱللَّٰه","a"],[" کا ذکر کرتے رہتے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani in his Sagheer, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.107)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمروؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ذکر کی مجلسوں کا ثواب کیا ہے؟ حضورؐ نے فرمایا ذکر کی مجلسوں کا ثواب، جنت ہے جنت۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.78) and Mundhiri (Vol.3 Pg.56)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا ذکر کی مجلسیں علم کے زندہ ہونے کا ذریعہ ہیں اور یہ مجلسیں دلوں میں خشوع پیدا کرتی ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.208)."]]}]},"100":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضورؐ جب کسی مجلس میں بیٹھتے یا نماز پڑھ لیتے تو کچھ کلمات پڑھا کرتے۔ میں نے حضورؐ سے ان کلمات کے بارے میں پوچھا تو فرمایا کہ ان کلمات کا فائدہ یہ ہے کہ آدمی نے اگر خیر کی بات کی ہو تو یہ کلمات اس پر قیامت کے دن تک کے لیے مہر بن جائیں گے اور اگر بری باتیں کی ہوں تو یہ کلمات ان کے لیے کفارہ بن جاتے ہیں اور وہ کلمات یہ ہیں",""]]],["q",[["سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ لَا إِلَٰهَ إِلَّا أَنتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میں تیری پاکی اور تیری تعریف بیان کرتا ہوں۔ تیرے سوا کوئی معبود نہیں میں تجھ سے مغفرت طلب کرتا ہوں اور تیری طرف توبہ کرتا ہوں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Dunya, Nasa'ee, Haakim and Bayhaqi."]]},{"b":[["n",[["حضرت ابوبرزہ اسلمیؓ","b"],[" فرماتے ہیں جب حضورؐ مجلس سے اٹھنے کا ارادہ فرماتے تو آخر میں یہ دعا پڑھتے",""]]],["q",[["سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ أَشْهَدُ أَن لَّا إِلَٰهَ إِلَّا أَنتَ أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ تو ایک آدمی نے پوچھا یا رسول اللہ! آپ کچھ کلمات پڑھتے ہیں پہلے تو آپ یہ کلمات نہیں پڑھا کرتے تھے۔ حضورؐ نے فرمایا مجلس میں جو غلطیاں ہو جاتی ہیں یہ کلمات ان کے لیے کفارہ ہیں۔ طبرانی نے حضرت رافع بن خدیجؓ سے اس جیسی حدیث ذکر کی ہے اس میں \"واتوب الیک\" کے بعد یہ کلمات بھی ہیں","a"]]],["q",[["عَمِلْتُ سُوءًا وَظَلَمْتُ نَفْسِي فَٱغْفِرْ لِي إِنَّهُۥ لَا يَغْفِرُ ٱلذُّنُوبَ إِلَّا أَنتَ","a"]]],["p",[["ترجمہ: \"اور میں نے جو بھی برا کام کیا یا اپنی جان پر ظلم کیا تو اسے معاف کر دے تیرے سوا اور کوئی بھی گناہوں کو معاف نہیں کرتا۔\" ہم لوگوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ کلمات آپ نے ابھی کہنے شروع کیے ہیں۔ حضورؐ نے فرمایا جی ہاں حضرت جبرائیلؑ میرے پاس آئے تھے اور انہوں نے کہا یہ کلمات مجلس کا کفارہ ہیں۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Abu Dawood."],["(3)","Nasa'ee, Haakim and Tabraani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.72)."]]},{"b":[["n",[["حضرت زبیر بن عوامؓ","b"],[" فرماتے ہیں ہم لوگوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب ہم آپ کے پاس سے اٹھ کر چلے جاتے ہیں تو ہم زمانہ جاہلیت کی باتیں شروع کر دیتے ہیں۔ حضورؐ نے فرمایا جب تم ایسی مجلسوں میں بیٹھو جن میں تمہیں اپنے بارے میں ڈر ہو (کہ تم سے غلط باتیں ہو گئی ہوں گی) تو اٹھتے وقت یہ کلمات پڑھ لیا کرو",""]]],["q",[["سُبْحَانَكَ ٱللَّهُمَّ وَبِحَمْدِكَ نَشْهَدُ أَن لَّا إِلَٰهَ إِلَّا أَنتَ نَسْتَغْفِرُكَ وَنَتُوبُ إِلَيْكَ اس مجلس میں جو کچھ ہوا ہوگا یہ کلمات اس کے لیے کفارہ بن جائیں گے۔","a"],[" (4)","s"]]]],"f":[["(4)","Tabraani in his Sagheer and Awsat. Haythami (Vol.10 Pg.142) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ","b"],[" فرماتے ہیں کچھ کلمات ایسے ہیں کہ جو شخص بھی کسی حق کی یا باطل کی مجلس سے اٹھتے وقت ان کلمات کو تین مرتبہ پڑھ لے گا تو یہ کلمات اس کی طرف سے (اس مجلس کی تمام غلطیوں کا) کفارہ ہو جائیں گے اور اگر (اس مجلس میں اس سے کوئی غلطی نہ ہوئی ہو بلکہ) وہ مجلس خیر کی اور ذکر کی تھی تو پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ ان کلمات کے ذریعہ ایسے مہر لگا دیتے ہیں جیسے انگوٹھی سے لکھی ہوئی تحریر پر لگائی جاتی ہے۔ پھر آگے حضرت عائشہؓ جیسی حدیث ذکر کی۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Dawood and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.72)."]]}]},"101":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے کچھ وصیت فرما دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" سے ڈرنے کو اپنے لیے ضروری سمجھو کیونکہ یہ تمام کاموں کی جڑ ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کچھ اور وصیت فرما دیں۔ آپؐ نے فرمایا قرآن کی تلاوت کو ضروری سمجھو کیونکہ تلاوت زمین پر تمہارے لیے نور اور آسمان میں تمہارے لیے ثواب کا ذخیرہ ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.8)."]]},{"b":[["n",[["حضرت اوس بن حذیفہ ثقفیؓ","b"],[" فرماتے ہیں کہ ہم قبیلہ ثقیف کا وفد بن کر حضورؐ کی خدمت میں حاضر ہوئے ہم میں سے جو احلافی تھے وہ حضرت مغیرہ بن شعبہؓ کے ہاں ٹھہرے اور مالکی حضرات کو حضورؐ نے اپنے خیمہ میں ٹھہرایا۔ حضورؐ عشاء کے بعد ہمارے پاس تشریف لاتے اور ہم سے (کھڑے کھڑے) باتیں کرتے اور اتنی دیر کھڑے رہتے کہ آپؐ (تھک جاتے اور) باری باری دونوں پاؤں پر آرام فرماتے، زیادہ تر آپؐ قریش کی شکایت کرتے اور فرماتے مکہ میں ہمیں کمزور سمجھا جاتا تھا۔ جب ہم مدینہ آ گئے تو ہم نے ان سے بدلہ لینا شروع کر دیا اور لڑائیوں میں کبھی وہ جیتتے اور کبھی ہم۔ حضورؐ روزانہ جس وقت ہمارے پاس تشریف لاتے ایک رات اس سے دیر سے تشریف لائے تو ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ روزانہ جس وقت ہمارے پاس تشریف لایا کرتے تھے آج اس سے دیر سے تشریف لائے ہیں (اس کی کیا وجہ ہے؟) آپؐ نے فرمایا میں نے قرآن کی ایک مقدار روزانہ پڑھنے کے لیے مقرر کر رکھی ہے وہ آج کسی وجہ سے پوری نہ ہو سکی اس لیے میں نے چاہا کہ اسے پورا کر کے پھر آپ لوگوں کے پاس آؤں۔ اگلے دن صبح کو ہم نے حضورؐ کے صحابہؓ سے پوچھا کہ انہوں نے قرآن ختم کرنے کے کتنے حصے بنا رکھے ہیں؟ انہوں نے بتایا کہ (قرآن ختم کرنے کے لیے) سات حصے بنا رکھے ہیں۔ پہلے حصے میں سورت فاتحہ کے بعد والی تین سورتیں، دوسرے حصے میں اس کے بعد والی پانچ سورتیں، تیسرے حصے میں اس کے بعد والی سات سورتیں، چوتھے حصے میں اس کے بعد والی نو سورتیں، پانچویں حصے میں اس کے بعد والی گیارہ سورتیں، چھٹے حصے میں اس کے بعد والی تیرہ سورتیں اور ساتویں حصے میں مفصل والی سورتیں۔ ابوداؤد کی روایت میں یہ ہے کہ حضورؐ نے فرمایا اسے پورا کیے بغیر میں آ جاؤں اسے میں نے اچھا نہ سمجھا۔",""],[" (2)","s"]]]],"f":[["(2)","Tayaalisi, Ahmad, Ibn Jareer, Tabraani and Abu Nu'aym in his Hilya (Vol.1 Pg.232). Abu Dawood (Vol.2 Pg.310) has reported a similar narration."]]},{"b":[["n",[["حضرت مغیرہ بن شعبہؓ","b"],[" فرماتے ہیں حضورؐ مکہ اور مدینہ کے درمیان ٹھہرے ہوئے تھے کہ اتنے میں ایک آدمی نے حضورؐ سے اندر آنے کی اجازت مانگی حضورؐ نے فرمایا روزانہ میں جتنا قرآن پڑھتا تھا آج رات وہ رہ گیا ہے اس پر میں کسی چیز کو ترجیح نہیں دے سکتا (میں وہ پڑھ رہا ہوں اس لیے ابھی اجازت نہیں ہے)۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abu Dawood in his Masaahif, as quoted in Kanzul Ummaal (Vol.1 Pg.226)."]]},{"b":[["n",[["حضرت ابوسلمہؒ","b"],[" کہتے ہیں حضرت عمر بن خطابؓ حضرت ابوموسیٰؓ سے فرمایا کرتے ہمیں ہمارے رب کی یاد دلاؤ تو حضرت ابوموسیٰؓ قرآن پڑھ کر سنایا کرتے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.258). Ibn Sa'd (Vol.4 Pg.109) has reported a similar narration."]]},{"b":[["n",[["حضرت حبیب بن ابی مرزوقؒ","b"],[" کہتے ہیں ہمیں یہ روایت پہنچی ہے کہ بعض دفعہ حضرت عمر بن خطابؓ حضرت ابوموسیٰؓ سے فرمایا کرتے ہمیں ہمارے رب کی یاد دلاؤ تو حضرت ابوموسیٰؓ قرآن پڑھا کرتے۔ وہ بہت اچھی آواز سے قرآن پڑھا کرتے تھے۔ ",""],["حضرت ابونضرہؒ","b"],[" کہتے ہیں حضرت عمرؓ نے حضرت ابوموسیٰؓ سے فرمایا ہمیں ہمارے رب کا شوق دلاؤ وہ قرآن پڑھنے لگے۔ لوگوں نے کہا نماز۔ حضرت عمرؓ نے فرمایا کیا ہم نماز میں نہیں ہیں؟",""]]]],"f":[]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضرت عمر بن خطابؓ جب گھر تشریف لے جاتے تو قرآن کھول کر اسے پڑھا کرتے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abu Dawood, as quoted in Kanzul Ummaal (Vol.1 Pg.224)."]]},{"b":[["n",[["حضرت عثمانؓ","b"],[" نے فرمایا میں یہ چاہتا ہوں کہ جو دن یا رات آئے میں اس میں قرآن دیکھ کر پڑھا کروں۔ حضرت عثمانؓ نے فرمایا اگر ہمارے دل پاک ہوتے تو ہم اپنے رب کے کلام سے کبھی بھی سیر نہ ہوتے اور مجھے یہ پسند نہیں ہے کہ میری زندگی میں کوئی دن ایسا آئے جس میں میں دیکھ کر قرآن نہ پڑھوں۔ چنانچہ حضرت عثمانؓ دیکھ کر اتنا زیادہ قرآن پڑھا کرتے تھے کہ ان کے انتقال سے پہلے ہی ان کا قرآن پھٹ گیا تھا۔",""],[" (6)","s"],[" (7)","s"],[" (8)","s"]]]],"f":[["(6)","Ahmad in his Zuhd and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.225)."],["(7)","Ahmad in his Zuhd and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.218)."],["(8)","Bayhaqi in his Asmaa was Sifaat (Pg.182)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا ہمیشہ دیکھ کر قرآن پڑھا کرو۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Abu Dawood, as quoted in Kanzul Ummaal (Vol.2 Pg.61)."]]},{"b":[["n",[["حضرت حبیب بن شہیدؒ","b"],[" کہتے ہیں کہ حضرت نافعؒ سے کسی نے پوچھا کہ حضرت ابن عمرؓ اپنے گھر میں کیا کیا کرتے تھے؟ انہوں نے کہا جو وہ کیا کرتے تھے لوگ اسے نہیں کر سکتے وہ ہر نماز کے لیے وضو کیا کرتے اور ہر دو نمازوں کے درمیان قرآن پڑھا کرتے۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Sa'd (Vol.4 Pg.170)."]]},{"b":[["n",[["حضرت ابن ابی ملیکہؒ","b"],[" کہتے ہیں حضرت عکرمہ بن ابی جہلؓ قرآن لے کر اپنے چہرے پر رکھا کرتے اور رونے لگ جاتے اور فرماتے یہ میرے رب کا کلام ہے یہ میرے رب کی کتاب ہے۔",""],[" (11)","s"]]]],"f":[["(11)","Haakim (Vol.3 Pg.243)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" نے فرمایا جو حضورؐ پر ایک مرتبہ درود بھیجتا ہے اس کے لیے دس نیکیاں لکھی جاتی ہیں اور یہ بھی فرمایا کہ جب تم میں سے کوئی آدمی بازار سے اپنے گھر والوں کے پاس واپس آئے تو اسے چاہیے کہ وہ قرآن کھول کر پڑھا کرے کیونکہ اسے ہر حرف کے بدلے دس نیکیاں ملیں گی۔ دوسری روایت میں یہ ہے کہ حضرت ابن عمرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے ہر حرف کے بدلے دس نیکیاں لکھیں گے میں یہ نہیں کہتا ہوں کہ \"الم\" پر دس نیکیاں ملیں گی بلکہ الف پر دس نیکیاں ملیں گی اور لام پر دس اور میم پر دس۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abu Dawood, as quoted in Kanzul Ummaal (Vol.1 Pg.219)."]]}]},"102":{"lead":[],"stories":[{"b":[["n",[["حضرت عقبہ بن عامر جہنیؓ","b"],[" فرماتے ہیں میری حضورؐ سے ملاقات ہوئی تو حضورؐ نے مجھے فرمایا اے عقبہ بن عامر! جو تم سے تعلق توڑے تم اس سے تعلق جوڑو جو تمہیں محروم رکھے (اور تمہیں نہ دے) تم اسے دیا کرو اور جو تم پر ظلم کرے تم اسے معاف کر دو۔ اس کے بعد میری حضورؐ سے پھر ملاقات ہوئی تو مجھ سے فرمایا اے عقبہ بن عامر! کیا میں تمہیں چند ایسی سورتیں نہ سکھا دوں کہ ان جیسی سورتیں ",""],["ٱللَّٰه","a"],[" نے تورات، زبور، انجیل اور قرآن کسی میں بھی نازل نہیں فرمائیں اور میں ہر رات انہیں ضرور پڑھتا ہوں",""]]],["q",[["قُلْ هُوَ ٱللَّهُ أَحَدٌ، قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ اور قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ جب سے حضورؐ نے مجھے ان سورتوں کے پڑھنے کا حکم دیا ہے اس وقت سے میں ہر رات ان کو ضرور پڑھتا ہوں اور جب حضورؐ نے مجھے ان کے پڑھنے کا حکم دیا ہے تو مجھ پر واجب ہو گیا ہے کہ انہیں نہ چھوڑوں۔","a"],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.223)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ جب رات کو اپنے بستر پر تشریف لاتے تو (قُلْ هُوَ ٱللَّهُ أَحَدٌ) اور (قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ) پڑھ کر دونوں ہاتھوں کو ملا کر اپنے اوپر دم کرتے اور جہاں تک ہو سکتا دونوں ہاتھ سارے جسم پر پھیرتے اپنے سر، چہرے اور جسم کے اگلے حصے سے اس کی ابتداء فرماتے اور اس طرح تین مرتبہ فرماتے۔ حضرت عائشہؓ فرماتی ہیں حضورؐ جب بستر پر تشریف لاتے تو قل ھو ",""],["ٱللَّٰه","a"],[" احد اور معوذتین (قل اعوذ برب الفلق اور قل اعوذ برب الناس) پڑھ کر دونوں ہاتھوں پر دم کرتے اور انہیں چہرے، بازو، سینے اور جسم پر جہاں تک ہاتھ پہنچتے پھیرتے۔ جب حضورؐ کی بیماری بڑھ گئی تو آپؐ نے مجھے حکم دیا کہ میں آپؐ کے ساتھ اس طرح کروں۔",""],[" (2)","s"],[" (3)","s"]]]],"f":[["(2)","Nasa'ee."],["(3)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.8 Pg.68). Jam'ul Fawaa'id has reported a similar narration from Bukhaari, Muslim, Abu Dawood, Tirmidhi and Ibn Maajah."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں نبی کریمؐ جب تک \"الم تنزیل\" اور \"تبارک الذی بیدہ الملک\" دونوں سورتیں پڑھ نہ لیتے نہ سوتے۔ ",""],["حضرت طاؤسؒ","b"],[" کہتے ہیں یہ دونوں سورتیں قرآن کی ہر سورت پر ستر نیکیاں زیادہ فضیلت رکھتی ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.76)."]]},{"b":[["n",[["حضرت عرباض بن ساریہؓ","b"],[" فرماتے ہیں حضورؐ جب بستر پر لیٹتے تو سونے سے پہلے مسبحات پڑھتے یعنی وہ سورتیں پڑھتے جن کے شروع میں \"سبح\" یا \"یسبح\" آتا ہے اور حضورؐ نے فرمایا ان سورتوں میں ایک ایسی آیت ہے جو ہزار آیتوں سے افضل ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Tirmidhi and Abu Dawood."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ جب تک حضورؐ سورت زمر اور سورت بنی اسرائیل پڑھ نہ لیتے سویا نہ کرتے۔",""],[" (6)","s"]]]],"f":[["(6)","Tirmidhi, as quoted in Jam'ul Fawaa'id (Vol.2 Pg.260)."]]},{"b":[["n",[["حضرت فروہ بن نوفلؓ","b"],[" فرماتے ہیں میں نے نبی کریمؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے کوئی ایسی چیز بتائیں جسے میں لیٹتے وقت پڑھ لیا کروں۔ آپؐ نے فرمایا",""]]],["q",[["قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ پڑھا کرو کیونکہ اس سورت میں شرک سے بیزاری ہے۔","a"],[" (7)","s"]]]],"f":[["(7)","Tirmidhi (Vol.2 Pg.176)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں آدمی کے پاس اس کی قبر میں عذاب کے فرشتے آئیں گے وہ پاؤں کی طرف سے آئیں گے تو پاؤں کہیں گے تمہارے لیے ہماری طرف سے کوئی راستہ نہیں ہے کیونکہ یہ سورت ملک پڑھا کرتا تھا پھر وہ سینہ کی طرف سے آئیں گے تو سینہ کہے گا تمہارے لیے میری طرف سے کوئی راستہ نہیں ہے کیونکہ یہ سورت ملک پڑھا کرتا تھا۔ پھر وہ سر کی طرف سے آئیں گے تو سر کہے گا تمہارے لیے میری طرف سے کوئی راستہ نہیں کیونکہ یہ سورت ملک پڑھا کرتا تھا۔ یہ سورت مانع ہے۔ یہ عذاب قبر کو روکتی ہے۔ اور تورات میں ہے کہ جس نے کسی رات میں اس سورت کو پڑھا اس نے بہت زیادہ ثواب حاصل کیا اور بہت عمدہ کام کیا۔ نسائی میں حدیث مختصر ہے اور ان الفاظ کے ساتھ ہے کہ جو ہر رات \"تبارک الذی بیدہ الملک\" پڑھے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے عذاب قبر سے بچائے گا اور ہم لوگ اسے حضورؐ کے زمانے میں مانعہ کہا کرتے تھے یعنی عذاب قبر کو روکنے والی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ کی کتاب میں یہ ہے کہ یہ ایسی سورت ہے کہ جو اسے ہر رات پڑھے گا وہ بہت زیادہ ثواب کمانے والا اور بہت عمدہ کام کرنے والا ہوگا۔",""],[" (8)","s"],[" (9)","s"]]]],"f":[["(8)","Haakim."],["(9)","Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.38). Bayhaqi has reported a similar narration in greater detail in his Kitaab Adhaabil Qabr, as quoted in Kanzul Ummaal (Vol.1 Pg.223)."]]},{"b":[["n",[["حضرت عمر بن خطابؓ","b"],[" نے فرمایا جو شخص سورت بقرہ، سورت آل عمران اور سورت نساء کسی رات میں پڑھے گا اسے قانتین یعنی فرمانبرداروں میں لکھ دیا جائے گا۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Ubaydah, Sa'eed bin Mansoor, Abd bin Humayd and Bayhaqi in his Shu'abul Imaan, as quoted in Kanzul Ummaal (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت جبیر بن مطعمؓ","b"],[" فرماتے ہیں حضورؐ نے مجھ سے فرمایا اے جبیر! کیا تم یہ پسند کرتے ہو کہ جب تم سفر میں جایا کرو تو تمہاری حالت سب سے اچھی اور تمہارا توشہ سب سے زیادہ ہو؟ میں نے عرض کیا جی ہاں میرے ماں باپ آپ پر قربان ہوں۔ آپؐ نے فرمایا تم یہ پانچ سورتیں پڑھا کرو",""]]],["q",[["قُلْ يَـٰٓأَيُّهَا ٱلْكَـٰفِرُونَ، إِذَا جَآءَ نَصْرُ ٱللَّهِ وَٱلْفَتْحُ، قُلْ هُوَ ٱللَّهُ أَحَدٌ، قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ اور قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ اور ہر سورت کے شروع میں بھی \"بسم اللہ الرحمٰن الرحیم\" پڑھو اور آخر میں بھی \"بسم اللہ الرحمٰن الرحیم\" پڑھو (اس طرح سورتیں پانچ ہوں گی اور بسم اللہ چھ مرتبہ ہوگی)۔ حضرت جبیرؓ فرماتے ہیں حالانکہ میں غنی اور مالدار تھا لیکن جب میں سفر میں جایا کرتا تھا تو میں سب سے زیادہ خستہ حالت اور سب سے کم توشہ والا ہوتا تھا تو جب مجھے حضورؐ نے یہ سورتیں سکھائیں اور میں نے انہیں پڑھنا شروع کیا تو میں سب سے اچھی حالت والا اور سب سے زیادہ توشہ والا ہو گیا اور پورے سفر میں واپسی تک میرا یہی حال رہتا ہے۔","a"],[" (11)","s"]]]],"f":[["(11)","Abu Ya'la. Haythami (Vol.10 Pg.134) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن خبیبؓ","b"],[" فرماتے ہیں ایک رات بہت زیادہ بارش ہوئی تھی اور سخت اندھیرا چھایا ہوا تھا ہم لوگ حضورؐ کو تلاش کرنے کے لیے نکلے تا کہ آپؐ ہمیں نماز پڑھا دیں۔ آخر آپؐ ہمیں مل گئے۔ آپؐ نے مجھ سے فرمایا کہو۔ میں نے کچھ نہ کہا۔ آپؐ نے دوبارہ فرمایا کہو میں نے کچھ نہ کہا آپؐ نے تیسری مرتبہ فرمایا کہو میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں کیا کہوں؟ آپؐ نے فرمایا صبح اور شام تین مرتبہ \"قل ھو ",""],["ٱللَّٰه","a"],[" احد\" اور معوذتین پڑھا کرو یہ تمہیں ہر چیز سے کفایت کرے گا۔",""],[" (12)","s"]]]],"f":[["(12)","Abu Dawood and Tirmidhi, as quoted in the Adhkaar of Nawawi (Pg.96)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا جو صبح کی نماز کے بعد دس مرتبہ \"قل ھو ",""],["ٱللَّٰه","a"],[" احد\" پڑھے گا وہ سارا دن گناہوں سے محفوظ رہے گا چاہے شیطان کتنا ہی زور لگائے۔",""],[" (13)","s"]]]],"f":[["(13)","Sa'eed bin Mansoor and Ibn Darees, as quoted in Kanzul Ummaal (Vol.1 Pg.223)."]]}]},"103":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں میں نے اس منبر کی لکڑیوں پر حضورؐ کو فرماتے ہوئے سنا کہ جو ہر نماز کے بعد آیۃ الکرسی پڑھے اسے جنت میں جانے سے موت کے علاوہ اور کوئی چیز روکنے والی نہیں ہوگی اور جو اسے بستر پر لیٹتے وقت پڑھے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے اس کے گھر پر اس کے پڑوسی کے گھر پر اس کے ارد گرد کے چند اور گھروں پر امن عطا فرمائیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Bayhaqi in his Shu'abul Imaan, as quoted in Kanzul Ummaal (Vol.1 Pg.221)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا مجھے ایسا کوئی آدمی نظر نہیں آتا جو پیدائشی مسلمان ہو یا بالغ ہو کر مسلمان ہوا ہو اور اس آیت",""]]],["q",[["ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلْحَىُّ ٱلْقَيُّومُ کو پڑھے بغیر رات گزارتا ہو کاش کہ آپ لوگ جان لیتے کہ اس آیت کا درجہ کتنا بڑا ہے۔ یہ آیت آپ لوگوں کے نبی کو اس خزانے سے دی گئی ہے جو عرش کے نیچے ہے اور آپ لوگوں کے نبی سے پہلے کسی نبی کو نہیں دی گئی اور میں اسے ہر رات تین مرتبہ پڑھ کر سوتا ہوں۔ عشاء کے بعد کی دو رکعتوں میں اور وتر میں بھی اسے پڑھتا ہوں اور بستر پر لیٹتے وقت بھی پڑھتا ہوں۔","a"],[" (2)","s"]]]],"f":[["(2)","Abu Ubayd, Ibn Abi Shaybah, Daarimi and others, as quoted in Kanzul Ummaal (Vol.1 Pg.221)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں میں نے کوئی ایسا عاقل بالغ آدمی نہیں دیکھا جو سورت بقرہ کی آخری آیتوں کو پڑھے بغیر سو جاتا ہو کیونکہ یہ آیتیں اس خزانے سے آئی ہیں جو عرش کے نیچے ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Daarimi, Musaddad, Muhammad bin Nasr, Ibn Dar'ees and Ibn Mardway, as quoted in Kanzul Ummaal (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت عثمانؓ","b"],[" فرماتے ہیں جو آدمی رات میں سورت آل عمران کی آخری آیتیں پڑھے گا اس کے لیے رات بھر کی عبادت کا ثواب لکھا جائے گا۔",""],[" (4)","s"]]]],"f":[["(4)","Daarimi, as quoted in Kanzul Ummaal (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ نے فرمایا جو رات کو کسی گھر میں سورت بقرہ کی دس آیتیں پڑھے گا اس گھر میں صبح تک کوئی شیطان داخل نہیں ہوگا۔ وہ دس آیتیں یہ ہیں سورت بقرہ کی شروع کی چار آیتیں، آیت الکرسی، اس کے بعد کی دو آیتیں اور سورت بقرہ کی آخری تین آیتیں۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani. Haythami (Vol.10 Pg.118) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" کے کھلیان میں کھجوریں رکھی ہوئی تھیں اور وہ ان کی نگرانی کرتے تھے۔ انہیں محسوس ہوا کہ یہ کھجوریں کم ہو رہی ہیں تو انہوں نے ایک رات ان کھجوروں کا پہرہ دیا تو انہوں نے ایک جانور دیکھا جو بالغ لڑکے جیسا تھا فرماتے ہیں میں نے اسے سلام کیا اس نے میرے سلام کا جواب دیا۔ میں نے کہا جنات کی شکل و صورت ایسی ہوتی ہے؟ اس نے کہا تمام جنات کو معلوم ہے کہ ان میں مجھ سے زیادہ طاقتور کوئی نہیں ہے۔ میں نے کہا تم نے (کھلیان سے کھجوریں چرانے کا کام) کیوں کیا؟ اس نے کہا ہمیں خبر ملی ہے کہ آپ کو صدقہ کرنا بہت پسند ہے تو ہم نے چاہا کہ ہمیں بھی آپ کی کچھ کھجوریں مل جائیں۔ میں نے کہا وہ کونسی چیز ایسی ہے جس کی وجہ سے ہماری تم لوگوں سے حفاظت ہو جائے؟ اس نے کہا یہ آیت الکرسی ہے جو سورت بقرہ میں ہے جو اسے شام کو پڑھے گا وہ صبح تک ہم سے محفوظ رہے گا اور جو اسے صبح کو پڑھے گا وہ شام تک ہم سے محفوظ رہے گا۔ صبح کو حضرت ابیؓ نے جا کر یہ سارا واقعہ حضورؐ کو بتایا تو حضورؐ نے فرمایا اس خبیث نے سچ کہا۔",""],[" (6)","s"]]]],"f":[["(6)","Nasa'ee, Haakim, Tabraani, Abu Nu'aym, Bayhaqi, Sa'eed bin Mansoor and others, as quoted in Kanzul Ummaal (Vol.1 Pg.221). Tabraani has reported a similar narration from reliable sources as confirmed by Haythami (Vol.10 Pg.118)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن بسرؓ","b"],[" فرماتے ہیں میں حمص سے چلا اور رات کو زمین کے ایک خاص ٹکڑے میں پہنچا تو اس علاقے کے جنات میرے پاس آ گئے اس پر میں نے سورت اعراف کی یہ آیت آخر تک پڑھی",""]]],["q",[["إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ ۗ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ ۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَـٰلَمِينَ  (سورۃ اعراف: ۵۴)","a"]]],["p",[["ترجمہ: \"بے شک تمہارا رب ",""],["ٱللَّٰه","a"],[" ہی ہے جس نے سب آسمانوں اور زمین کو چھ روز میں پیدا کیا پھر عرش پر قائم ہوا۔ چھپا دیتا ہے شب سے دن کو ایسے طور پر کہ وہ شب اس دن کو جلدی سے آ لیتی ہے اور سورج اور چاند اور دوسرے ستاروں کو پیدا کیا ایسے طور پر کہ سب اس کے حکم کے تابع ہیں۔ یاد رکھو ",""],["ٱللَّٰه","a"],[" ہی کے لیے خالق ہونا اور حاکم ہونا۔ بڑی خوبیوں کے بھرے ہوئے ہیں ",""],["ٱللَّٰه","a"],[" تعالیٰ جو تمام عالم کے پروردگار ہیں۔\" اس پر ان جنات نے ایک دوسرے سے کہا اب تو صبح تک اس کا پہرہ دو (چنانچہ انھوں نے ساری رات میرا پہرہ دیا) صبح کو میں سواری پر سوار ہو کر وہاں سے چل دیا۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani. Haythami (Vol.10 Pg.133) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت علاء بن لجلاجؒ","b"],[" نے اپنے بیٹوں سے کہا جب تم مجھے قبر میں رکھنے لگو تو",""]]],["q",[["بِسْمِ ٱللَّهِ وَعَلَىٰ مِلَّةِ رَسُولِ ٱللَّهِ ﷺ کہہ کر مجھے قبر میں رکھنا اور میری قبر پر آہستہ آہستہ مٹی ڈالنا اور میرے سرہانے سورت بقرہ کی شروع کی اور آخر کی آیتیں پڑھنا کیونکہ میں نے حضرت ابن عمرؓ کو دیکھا کہ وہ ایسا کرنے کو بہت پسند کرتے تھے۔","a"],[" (8)","s"]]]],"f":[["(8)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.8 Pg.119)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ جو یہ چاہتا ہے کہ اس کا اجر و ثواب بہت بڑے اور مکمل پیمانے میں تولا جائے تو وہ یہ آیتیں تین مرتبہ پڑھے",""]]],["q",[["سُبْحَـٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ  (سورۃ صافات: ۱۸۰)","a"]]],["p",[["ترجمہ: \"آپ کا رب جو بڑی عظمت والا ہے ان باتوں سے پاک ہے جو یہ (کافر) بیان کرتے ہیں۔\"",""],[" (9)","s"]]]],"f":[["(9)","Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.1 Pg.222)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عبید بن عمیرؒ","b"],[" کہتے ہیں کہ حضرت عبدالرحمٰن بن عوفؓ جب اپنے گھر میں داخل ہوتے تو اس کے تمام کونوں میں آیت الکرسی پڑھتے۔",""],[" (10)","s"]]]],"f":[["(10)","Abu Ya'la. Haythami (Vol.10 Pg.128) has commented on the chain of narrators."]]}]},"104":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! قیامت کے دن لوگوں میں سے کسے آپ کی شفاعت کی سعادت سب سے زیادہ حاصل ہوگی؟ حضورؐ نے فرمایا چونکہ مجھے معلوم تھا کہ تمہیں احادیث حاصل کرنے کا بہت زیادہ شوق ہے اس وجہ سے میرا خیال یہی تھا کہ تم سے پہلے یہ بات مجھ سے کوئی نہیں پوچھے گا۔ قیامت کے دن میری شفاعت کی سعادت سب سے زیادہ اسے حاصل ہوگی جو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" خالص دل سے کہے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.72)."]]},{"b":[["n",[["حضرت زید بن ارقمؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" اخلاص سے کہے گا وہ جنت میں داخل ہوگا۔ کسی نے پوچھا اس کا اخلاص کیا ہے؟ آپؐ نے فرمایا اس کا اخلاص یہ ہے کہ یہ کلمہ انسان کو ",""],["ٱللَّٰه","a"],[" کے حرام کردہ کاموں سے روک دے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani in his Awsat, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.74)."]]},{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا ایک مرتبہ حضرت موسیٰ علیہ السلام نے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی بارگاہ میں عرض کیا کہ مجھے کوئی ورد سکھا دیں جس سے آپ کو یاد کیا کروں اور آپ کو پکارا کروں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہا کرو۔ انھوں نے عرض کیا اے میرے پروردگار! یہ تو ساری ہی دنیا کہتی ہے۔ ارشاد ہوا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہا کرو۔ عرض کیا اے میرے رب! میں تو کوئی ایسی خاص چیز مانگتا ہوں جو مجھ ہی کو عطا ہو۔ ارشاد ہوا کہ اگر ساتوں آسمان اور ساتوں زمینیں ایک پلڑے میں رکھ دی جائیں اور دوسری طرف ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" رکھ دیا جائے تو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" والا پلڑا جھک جائے گا۔ اور ایک روایت میں یہ ہے کہ اگر ساتوں آسمان اور میرے علاوہ انہیں آباد کرنے والے اور ساتوں زمینیں ایک پلڑے میں ہوں اور ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" دوسرے پلڑے میں ہو تو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" والا پلڑا جھک جائے گا۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Nasa'ee, Ibn Hibbaan and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.75)."],["(4)","Abu Ya'la. Haythami (Vol.10 Pg.82) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے فرمایا کیا میں تمہیں یہ نہ بتاؤں کہ حضرت نوح علیہ السلام نے اپنے بیٹے کو کیا وصیت کی تھی؟ صحابہؓ نے عرض کیا ضرور بتائیں۔ ارشاد فرمایا حضرت نوحؑ نے اپنے بیٹے کو یہ وصیت کی تھی کہ اے میرے بیٹے! میں تمہیں دو باتوں کی وصیت کرتا ہوں اور دو باتوں سے روکتا ہوں۔ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہنے کی وصیت کرتا ہوں کیونکہ اگر یہ کلمہ ایک پلڑے میں رکھ دیا جائے اور دوسرے پلڑے میں سارے آسمان اور زمینیں رکھ دی جائیں تو کلمہ والا پلڑا جھک جائے گا اور اگر سارے آسمان ایک حلقہ بن جائیں تو بھی یہ کلمہ انہیں توڑ کر آگے چلا جائے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ تک پہنچ کر رہے گا اور دوسری وصیت یہ کرتا ہوں کہ سبحان ",""],["ٱللَّٰه","a"],[" العظیم و بحمدہ کہا کرو کیونکہ یہ ساری مخلوق کی عبادت ہے اور اسی کی برکت سے ان کو رزق دیا جاتا ہے اور فرمایا تمہیں دو باتوں سے روکتا ہوں ایک شرک دوسرا تکبر کیونکہ یہ دونوں بری صفات ",""],["ٱللَّٰه","a"],[" سے روک دیتی ہیں۔ کسی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! کیا یہ بات تکبر میں سے ہے کہ آدمی کھانا تیار کرے اور اس کھانے پر ایک جماعت کو بلائے اور انہیں کھلائے یا صاف ستھرے کپڑے پہنے؟ آپؐ نے فرمایا نہیں یہ دونوں باتیں تکبر میں سے نہیں ہیں۔ تکبر تو یہ ہے کہ تم مخلوق کو بے وقوف بناؤ اور دوسرے لوگوں کو حقیر سمجھو۔ ایک روایت میں یہ ہے کہ اگر تمام آسمان اور زمینیں اور جو کچھ ان میں ہے یہ سب ایک حلقہ بن جائے اور ان پر ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" رکھ دیا جائے تو یہ کلمہ ان سب کو توڑ دے گا۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Bazzaar. Haythami (Vol.10 Pg.84) has commented on the chain of narrators. Haakim has reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.77)."],["(6)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.77)."]]},{"b":[["n",[["حضرت یعلیٰ بن شدادؒ","b"],[" کہتے ہیں میرے والد حضرت شداد بن اوسؓ نے جب مجھے یہ واقعہ بیان کیا اس وقت حضرت عبادہ بن صامتؓ وہاں موجود تھے اور وہ میرے والد کی تصدیق کر رہے تھے۔ میرے والد نے مجھے بتایا کہ ایک دن ہم لوگ نبی کریمؐ کے پاس بیٹھے ہوئے تھے آپؐ نے فرمایا کیا تم میں کوئی اجنبی آدمی اہل کتاب میں سے ہے؟ ہم نے عرض کیا کوئی نہیں۔ ارشاد فرمایا کواڑ بند کر دو۔ اس کے بعد فرمایا ہاتھ اٹھاؤ اور کہو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" ہم نے تھوڑی دیر ہاتھ اٹھائے رکھے (اور کلمہ طیبہ پڑھا) پھر فرمایا الحمد للہ! اے ",""],["ٱللَّٰه","a"],["! تو نے مجھے یہ کلمہ دے کر بھیجا ہے اور اس پر تو نے مجھے حکم دیا ہے اور اس پر تو نے مجھ سے جنت کا وعدہ کیا ہے اور تو وعدہ کے خلاف نہیں کرتا پھر فرمایا کہ خوش ہو جاؤ ",""],["ٱللَّٰه","a"],[" نے تمہاری مغفرت فرما دی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Tabraani and others, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.75). Haythami (Vol.10 Pg.81) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے کچھ وصیت فرما دیں۔ ارشاد فرمایا جب تم سے کوئی برائی سرزد ہو جائے تو اس کے بعد فوراً کوئی نیکی کا کام کرو اس سے وہ برائی مٹ جائے گی۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" بھی نیکیوں میں سے ہے؟ آپؐ نے فرمایا یہ تو تمام نیکیوں سے افضل ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad. Haythami (Vol.10 Pg.81) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عمر بن خطابؓ","b"],[" نے دیکھا کہ لوگ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" اور ",""],["ٱللَّٰه","a"],[" اکبر کہہ رہے ہیں تو آپؓ نے فرمایا رب کعبہ کی قسم! یہی ہے یہی ہے۔ لوگوں نے پوچھا یہی کیا ہے؟ آپؓ نے فرمایا یہی تقویٰ والا کلمہ ہے۔ مسلمان ہی اس کے زیادہ مستحق ہیں اور اس کے اہل ہیں۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ارشاد فرمایا ہے",""]]],["q",[["وَأَلْزَمَهُمْ كَلِمَةَ ٱلتَّقْوَىٰ  (سورۃ فتح: ۲۶)","a"]]],["p",[["ترجمہ: \"اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مسلمانوں کو تقویٰ کی بات پر جمائے رکھا۔\" اس کے بارے میں حضرت علیؓ نے فرمایا یہ تقویٰ والی بات ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" ہے۔ ابن جریر وغیرہ میں اس کے بعد ",""],["ٱللَّٰه","a"],[" اکبر بھی ہے۔",""],[" (9)","s"],[" (10)","s"],[" (11)","s"]]]],"f":[["(9)","Ibn Khusru, as quoted in Kanzul Ummaal (Vol.1 Pg.207)."],["(10)","Abdur Razzaaq, Ibn Jareer, Ibn Mundhir, Ibn Abi Haatim, Haakim and Bayhaqi in his Asmaa, as quoted in Kanzul Ummaal (Vol.1 Pg.265)."],["(11)","Ibn Jareer and others, as quoted in Kanzul Ummaal (Vol.1 Pg.265)."]]}]},"105":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا باقیات صالحات کثرت سے پڑھا کرو۔ صحابہؓ نے پوچھا باقیات صالحات کیا چیزیں ہیں؟ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" اکبر و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" وسبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ ولا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],[" کہنا۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, Abu Ya'la, Nasa'ee, Ibn Hibbaan and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.91). Ahmad and Abu Ya'la report from reliable sources as confirmed by Haythami (Vol.10 Pg.87)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا تم لوگ اپنی حفاظت کا سامان لے لو۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا کوئی دشمن آ گیا ہے؟ آپؐ نے فرمایا نہیں بلکہ آگ سے حفاظت کا سامان لے لو اور سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر کہا کرو کیونکہ یہ کلمات تم سے آگے جا کر آخرت میں کام آئیں گے اور تمہارے اچھے انجام کا سبب بنیں گے اور یہی وہ اعمال صالحہ ہیں جن کا ثواب باقی رہتا ہے۔ ایک روایت میں یہ ہے کہ یہی نجات دینے والے کلمات ہیں اور اوسط میں طبرانی کی روایت میں ولا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],[" کا اضافہ بھی ہے۔",""],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(2)","Nasa'ee, Haakim and Bayhaqi."],["(3)","Haakim."],["(4)","Tabraani in his Awsat, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.92)."]]},{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا کیا تم اس بات کی طاقت رکھتے ہو کہ روزانہ احد پہاڑ کے برابر عمل کر لیا کرو؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کون روزانہ احد پہاڑ کے برابر عمل کر سکتا ہے؟ آپؐ نے فرمایا تم سب کر سکتے ہو۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیسے؟ آپؐ نے فرمایا سبحان ",""],["ٱللَّٰه","a"],[" کہنا احد سے بڑا ہے اور الحمد للہ کہنا احد سے بڑا ہے اور ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہنا احد سے بڑا ہے اور ",""],["ٱللَّٰه","a"],[" اکبر کہنا احد سے بڑا ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Dunya, Nasa'ee, Tabraani and Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.91) and Mundhiri (Vol.3 Pg.94)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں میں پودا لگا رہا تھا کہ اتنے میں حضورؐ میرے پاس سے گزرے اور فرمایا اے ابوہریرہ! کیا لگا رہے ہو؟ میں نے عرض کیا پودا لگا رہا ہوں۔ فرمایا کیا میں تمہیں اس سے بہتر پودا نہ بتا دوں؟ سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر کہنا ان میں سے ہر کلمہ کے بدلے جنت میں ایک درخت لگ جائے گا۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Maajah and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.84)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جب تم جنت کے باغوں پر گزرو تو خوب چرو۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جنت کے باغ کیا ہیں؟ آپؐ نے فرمایا مسجدیں۔ میں نے عرض کیا ان میں چرنے کی کیا صورت ہے؟ آپؐ نے فرمایا سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر کہنا۔",""],[" (7)","s"]]]],"f":[["(7)","Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.97)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں ایک مرتبہ حضورؐ نے ایک ٹہنی پکڑ کر اسے ہلایا تا کہ اس کے پتے گریں لیکن کوئی پتہ نہ گرا۔ آپؐ نے اسے پھر ہلایا تو پھر بھی کوئی پتہ نہ گرا آپؐ نے تیسری مرتبہ ہلایا تو پھر پتے گرنے لگے اس پر حضورؐ نے فرمایا سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر کہنے سے گناہ ایسے گر جاتے ہیں جیسے درخت سے پتے۔",""],[" (8)","s"]]]],"f":[["(8)","Ahmad, reporting from reliable sources as confirmed in Targheeb wat Tarheeb (Vol.3 Pg.93). Tirmidhi has reported a similar narration."]]},{"b":[["n",[["حضرت سعد بن ابی وقاصؓ","b"],[" فرماتے ہیں ایک دیہاتی نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا کہ آپ مجھے ایسا کلام بتا دیں جسے میں پڑھتا رہوں۔ آپؐ نے فرمایا تم یہ پڑھا کرو",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُۥ لَا شَرِيكَ لَهُۥ، ٱللَّهُ أَكْبَرُ كَبِيرًا وَٱلْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ ٱللَّهِ رَبِّ ٱلْعَـٰلَمِينَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ ٱلْعَزِيزِ ٱلْحَكِيمِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں، ",""],["ٱللَّٰه","a"],[" سب سے بڑا ہے بہت بڑا اور ",""],["ٱللَّٰه","a"],[" ہی کے لیے بہت تعریف ہے اور پاک ہے ",""],["ٱللَّٰه","a"],[" جو تمام جہانوں کا رب ہے، اور گناہ سے بچنے کی طاقت اور نیکی کرنے کی قوت صرف ",""],["ٱللَّٰه","a"],[" کی مدد سے ہے جو غالب اور حکمت والا ہے۔\" اس نے کہا یہ تمام کلمات تو میرے رب کی تعریف کے ہو گئے مجھے اپنے لیے کیا ملا؟ آپؐ نے فرمایا تم یہ دعا مانگا کرو",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِى وَٱرْحَمْنِى وَٱهْدِنِى وَٱرْزُقْنِى","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری مغفرت فرما، مجھ پر رحم فرما، مجھے ہدایت عطا فرما اور مجھے رزق نصیب فرما۔\" حضرت ابومالک اشجعیؓ کی روایت میں ہے \"مجھے عافیت نصیب فرما\"۔ ایک روایت میں یہ ہے کہ اس دعا میں تمہاری دنیا اور آخرت دونوں آ گئیں۔",""],[" (9)","s"]]]],"f":[["(9)","Muslim."]]},{"b":[["n",[["حضرت ابن ابی اوفیؓ","b"],[" فرماتے ہیں ایک دیہاتی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے قرآن سیکھنے کی بہت کوشش کی لیکن سیکھ نہ سکا۔ اب آپ مجھے کوئی ایسی چیز سکھا دیں جو قرآن کی جگہ بھی ہو جائے۔ آپؐ نے فرمایا سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر پڑھا کرو۔ اس نے انگلیوں پر گنتے ہوئے یہ کلمات کہے اور پھر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! یہ سارے کلمات تو میرے رب کی تعریف کے ہو گئے خود میرے لیے کیا ہوا؟ آپؐ نے فرمایا تم یہ دعا مانگا کرو",""]]],["q",[["ٱللَّهُمَّ ٱغْفِرْ لِى وَٱرْحَمْنِى وَعَافِنِى وَٱهْدِنِى وَٱرْزُقْنِى","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! میری مغفرت فرما، مجھ پر رحم فرما، مجھے عافیت دے، مجھے ہدایت دے اور مجھے رزق دے۔\" یہ سن کر دیہاتی چل دیا۔ آپؐ نے فرمایا یہ دیہاتی دونوں ہاتھوں کو خیر سے بھر کر جا رہا ہے۔ بیہقی کی روایت میں \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\" بھی ہے۔",""],[" (10)","s"],[" (11)","s"]]]],"f":[["(10)","Ibn Abi Dunya."],["(11)","Bayhaqi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.90). Abu Dawood has reported a similar narration."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا کیا میں تجھے وہ کلام نہ بتاؤں جو ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ پسند ہے؟ میں نے عرض کیا مجھے وہ کلام ضرور بتائیں جو ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ پسند ہے۔ فرمایا ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ پسند کلام \"سبحان ",""],["ٱللَّٰه","a"],[" و بحمدہ\" ہے۔ ترمذی کی روایت میں \"سبحان ربی و بحمدہ\" ہے۔ مسلم کی ایک روایت میں یہ ہے کہ حضورؐ سے پوچھا گیا کونسا کلام سب سے افضل ہے؟ فرمایا وہ کلام جو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے فرشتوں کے لیے یا اپنے بندوں کے لیے چنا اور وہ ہے \"سبحان ",""],["ٱللَّٰه","a"],[" و بحمدہ\"۔",""],[" (12)","s"],[" (13)","s"],[" (14)","s"]]]],"f":[["(12)","Muslim and Nasa'ee."],["(13)","Tirmidhi."],["(14)","Muslim."]]},{"b":[["n",[["حضرت ابوطلحہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا جو آدمی ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہے گا وہ جنت میں ضرور داخل ہوگا یا فرمایا جنت اس کے لیے واجب ہو جائے گی اور جو آدمی سو مرتبہ \"سبحان ",""],["ٱللَّٰه","a"],[" و بحمدہ\" کہے گا اس کے لیے ایک لاکھ چوبیس ہزار نیکیاں لکھی جائیں گی۔ صحابہؓ نے عرض کیا پھر تو ہم میں سے کوئی بھی ہلاک نہ ہوگا۔ آپؐ نے فرمایا ہاں لیکن بات یہ ہے کہ آدمی اتنی نیکیاں لے کر آئے گا کہ کسی پہاڑ پر رکھ دی جائیں تو وہ پہاڑ دب جائے لیکن پھر نعمتیں آئیں گی اور ان کے بدلے میں وہ نیکیاں سب ختم ہو جائیں گی۔ اس کے بعد پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ ہی اپنی رحمت اور فضل سے دستگیری فرمائیں گے۔",""],[" (15)","s"]]]],"f":[["(15)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.81)."]]},{"b":[["n",[["حضرت سعدؓ","b"],[" فرماتے ہیں ہم لوگ حضورؐ کے پاس بیٹھے ہوئے تھے کہ اتنے میں آپؐ نے فرمایا کیا تم لوگ روزانہ ایک ہزار نیکیاں کمانے سے عاجز ہو؟ پاس بیٹھے ہوئے لوگوں میں سے ایک صاحب نے پوچھا کہ ہم کس طرح ایک ہزار نیکیاں کما سکتے ہیں؟ فرمایا آدمی سو دفعہ \"سبحان ",""],["ٱللَّٰه","a"],["\" کہے تو اس کے لیے ہزار نیکیاں لکھی جائیں گی یا اس کی ہزار خطائیں گرا دی جائیں گی۔ ترغیب میں ہے کہ مسلم کی روایت میں تو \"او\" ہے جس کا ترجمہ \"یا\" لکھا گیا ہے لیکن ترمذی اور نسائی کی روایت میں \"و\" ہے جس کا ترجمہ یہ ہوگا کہ اور اس کی ہزار خطائیں گرا دی جائیں گی۔ و",""],["ٱللَّٰه","a"],[" اعلم۔",""],[" (16)","s"]]]],"f":[["(16)","Muslim, Tirmidhi and Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.83). Ibn Abi Shaybah, Ahmad, Abd bin Humayd, Ibn Hibbaan and Abu Nu'aym have all reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت قیس بن سعد بن عبادہؓ","b"],[" فرماتے ہیں کہ میرے والد نے مجھے نبی کریمؐ کی خدمت میں خدمت کرنے کے لیے پیش کیا ایک دن حضورؐ میرے پاس تشریف لائے میں دو رکعت نماز پڑھ کر بیٹھا ہوا تھا آپؐ نے مجھے پاؤں مبارک مار کر فرمایا کیا میں تمہیں جنت کے دروازوں میں سے ایک دروازہ نہ بتا دوں؟ میں نے کہا ضرور بتائیں۔ فرمایا \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\" (برائیوں سے بچنے کی طاقت اور نیکیاں کرنے کی قوت صرف ",""],["ٱللَّٰه","a"],[" ہی سے ملتی ہے)۔",""],[" (17)","s"]]]],"f":[["(17)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.104)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں میں نبی کریمؐ کے پیچھے پیچھے چل رہا تھا کہ اتنے میں آپؐ نے مجھ سے فرمایا اے ابوذر! کیا میں تمہیں جنت کے خزانوں سے ایک خزانہ نہ بتاؤں؟ میں نے کہا ضرور بتائیں۔ فرمایا \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\"۔",""],[" (18)","s"]]]],"f":[["(18)","Ibn Maajah, Ibn Abi Dunya and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.105)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن سعد بن ابی وقاصؒ","b"],[" فرماتے ہیں مجھ سے حضرت ابوایوب انصاریؓ نے فرمایا کیا میں تمہیں ایسا کلمہ نہ سکھا دوں جو مجھے حضورؐ نے سکھایا تھا؟ میں نے کہا اے چچا جان! ضرور سکھائیں۔ فرمایا جب حضورؐ میرے مہمان بنے تھے تو ایک دن آپؐ نے فرمایا کیا میں تمہیں جنت کے خزانوں میں سے ایک خزانہ نہ بتا دوں؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں ضرور بتا دیں۔ فرمایا \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\" کثرت سے پڑھا کرو۔",""],[" (19)","s"]]]],"f":[["(19)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.98)."]]},{"b":[["n",[["حضرت ابوایوب انصاریؓ","b"],[" فرماتے ہیں معراج کی رات میں حضورؐ کا حضرت ابراہیم علیہ الصلوٰۃ والسلام پر گزر ہوا تو انہوں نے پوچھا اے جبرائیل! یہ آپ کے ساتھ کون ہیں؟ حضرت جبرائیلؑ نے کہا یہ حضرت محمدؐ ہیں تو حضرت ابراہیمؑ نے حضورؐ سے فرمایا اے محمد! اپنی امت سے کہنا کہ وہ جنت کے پودے کثرت سے لگائیں کیونکہ جنت کی مٹی بہت عمدہ ہے اور وہاں بہت کشادہ زمین ہے۔ حضورؐ نے پوچھا جنت کے پودے کیا ہیں؟ حضرت ابراہیمؑ نے فرمایا \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\"۔ طبرانی کی روایت میں یہ بھی ہے کہ حضرت ابراہیمؑ نے مجھے سلام کیا اور مجھے خوش آمدید کہا اور فرمایا اپنی امت سے کہنا۔",""],[" (20)","s"],[" (21)","s"]]]],"f":[["(20)","Ahmad, Ibn Abi Dunya and Ibn Hibbaan, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.105). Haythami (Vol.10 Pg.98) has commented on Ahmad's chain of narrators."],["(21)","Tabraani."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا جس نے \"بسم ",""],["ٱللَّٰه","a"],["\" کہا اس نے ",""],["ٱللَّٰه","a"],[" کا ذکر کیا اور جس نے \"الحمد للہ\" کہا اس نے ",""],["ٱللَّٰه","a"],[" کا شکر ادا کیا اور جس نے \"",""],["ٱللَّٰه","a"],[" اکبر\" کہا اس نے ",""],["ٱللَّٰه","a"],[" کی عظمت بیان کی اور جس نے \"",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["\" کہا اس نے ",""],["ٱللَّٰه","a"],[" کی توحید بیان کی اور جس نے \"لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["\" کہا اس نے فرمانبرداری کا اظہار کیا اور اس نے خود کو ",""],["ٱللَّٰه","a"],[" کے سپرد کر دیا اور اسے جنت میں اس کی وجہ سے روزی اور خزانہ ملے گا۔",""],[" (22)","s"]]]],"f":[["(22)","Abu Nu'aym in his Hilya (Vol.1 Pg.322)."]]},{"b":[["n",[["حضرت مطرفؒ","b"],[" کہتے ہیں مجھ سے حضرت عمرانؓ نے فرمایا آج میں تمہیں ایک بات بتاتا ہوں جس سے ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں بعد میں نفع دیں گے اور وہ یہ ہے کہ تم یہ بات جان لو کہ قیامت کے دن ",""],["ٱللَّٰه","a"],[" کے سب سے بہترین بندے وہ ہوں گے جو (دنیا میں) ",""],["ٱللَّٰه","a"],[" کی خوب حمد و ثنا کرنے والے ہوں گے۔",""],[" (23)","s"]]]],"f":[["(23)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.95)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ نے فرمایا \"سبحان ",""],["ٱللَّٰه","a"],["\" اور \"",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["\" کا تو ہمیں پتہ چل گیا لیکن \"الحمد للہ\" کیا ہے؟ حضرت علیؓ نے فرمایا ایسا کلمہ ہے جسے ",""],["ٱللَّٰه","a"],[" نے اپنے لیے پسند فرمایا ہے اور وہ چاہتے ہیں کہ اسے کہا جائے۔ ",""],["حضرت ابوظبیانؒ","b"],[" کہتے ہیں حضرت ابن کواءؒ نے حضرت علیؓ سے \"سبحان ",""],["ٱللَّٰه","a"],["\" کے بارے میں پوچھا تو حضرت علیؓ نے فرمایا یہ ایسا کلمہ ہے جسے ",""],["ٱللَّٰه","a"],[" نے اپنے لیے پسند فرمایا ہے اور اس میں ہر بری صفت سے ",""],["ٱللَّٰه","a"],[" کی پاکی بیان کرنا ہے۔",""],[" (24)","s"],[" (25)","s"]]]],"f":[["(24)","Ibn Abi Haatim."],["(25)","Askari in his Amthaal and Abul Hasan Bakaali, as quoted in Kanzul Ummaal (Vol.1 Pg.210)."]]},{"b":[["n",[["ایک مرتبہ حضرت عمرؓ نے دو آدمیوں کو مارنے کا حکم دیا تو ان میں سے ایک \"بسم ",""],["ٱللَّٰه","a"],["\" اور دوسرا \"سبحان ",""],["ٱللَّٰه","a"],["\" کہنے لگا حضرت عمرؓ نے مارنے والے سے کہا تیرا بھلا ہو \"سبحان ",""],["ٱللَّٰه","a"],["\" کہنے والے کی پٹائی ذرا ہلکی کرنا کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کا ہر عیب سے پاک ہونا صرف مومن ہی کے دل میں پختہ ہوتا ہے۔",""],[" (26)","s"]]]],"f":[["(26)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.210)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرمایا کرتے تھے جب بھی میں تمہیں کوئی بات بتاتا ہوں تو اس کے ساتھ ہی ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے وہ آیت ضرور لاتا ہوں جس سے میری اس بات کی تصدیق ہوتی ہے۔ مسلمان بندہ جب \"سبحان ",""],["ٱللَّٰه","a"],[" و الحمد للہ و",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و",""],["ٱللَّٰه","a"],[" اکبر و تبارک ",""],["ٱللَّٰه","a"],["\" کہتا ہے تو ایک فرشتہ ان کلمات کو لے کر اپنے پر کے نیچے رکھ لیتا ہے پھر انہیں لے کر اوپر چڑھتا ہے تو وہ فرشتوں کی جس جماعت پر بھی گزرتا ہے وہ ان کلمات کے کہنے والے کے لیے استغفار کرتے ہیں آخر وہ ان کلمات کو لے کر ",""],["ٱللَّٰه","a"],[" تعالیٰ کی ذات عالی تک پہنچ جاتا ہے پھر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے یہ آیت پڑھی",""]]],["q",[["إِلَيْهِ يَصْعَدُ ٱلْكَلِمُ ٱلطَّيِّبُ وَٱلْعَمَلُ ٱلصَّـٰلِحُ يَرْفَعُهُۥ  (سورۃ فاطر: ۱۰)","a"]]],["p",[["ترجمہ: \"اچھا کلام اسی تک پہنچتا ہے اور اچھا کام اس کو پہنچاتا ہے۔\"",""],[" (27)","s"]]]],"f":[["(27)","Tabraani. Haythami (Vol.10 Pg.90) has commented on the chain of narrators. Haakim has reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.93)."]]}]},"106":{"lead":[],"stories":[{"b":[["n",[["حضرت جویریہؓ","b"],[" فرماتی ہیں کہ نبی کریمؐ صبح کی نماز کے وقت میرے پاس سے نماز کے لیے تشریف لے گئے (اور میں اپنے مصلے پر بیٹھی ہوئی تھی) حضورؐ چاشت کی نماز کے بعد (دوپہر کے قریب) تشریف لائے تو میں اسی حال میں بیٹھی ہوئی تھی۔ حضورؐ نے پوچھا تم اسی حال پر ہو جس پر میں نے تمہیں چھوڑا تھا؟ میں نے کہا جی ہاں۔ آپؐ نے فرمایا میں نے تم سے جدا ہونے کے بعد چار کلمے تین مرتبہ پڑھے۔ اگر ان کو اس سب کے مقابلہ میں تولا جائے جو تم نے صبح سے پڑھا ہے تو وہ غالب ہو جائیں، وہ کلمے یہ ہیں",""]]],["q",[["سُبْحَانَ ٱللَّهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَاءَ نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کی پاکی بیان کرتا ہوں اور اس کی تعریف کرتا ہوں اس کی مخلوقات کی تعداد کے برابر اور اس کی مرضی اور خوشنودی کے برابر اور اس کے عرش کے وزن کے برابر اور اس کے کلمات کی مقدار کے برابر۔\" مسلم کی روایت میں اس طرح ہے",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ خَلْقِهِ، سُبْحَانَ ٱللَّهِ رِضَا نَفْسِهِ، سُبْحَانَ ٱللَّهِ زِنَةَ عَرْشِهِ، سُبْحَانَ ٱللَّهِ مِدَادَ كَلِمَاتِهِ نسائی میں اس کے بعد یہ ہے کہ \"الحمد للہ\" بھی اسی طرح چار مرتبہ۔ نسائی کی دوسری روایت میں یہ کلمات اس طرح ہیں","a"]]],["q",[["سُبْحَانَ ٱللَّهِ وَبِحَمْدِهِ وَلَا إِلَٰهَ إِلَّا ٱللَّهُ وَٱللَّهُ أَكْبَرُ عَدَدَ خَلْقِهِ وَرِضَاءَ نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ","a"],[" (1)","s"],[" (2)","s"],[" (3)","s"],[" (4)","s"]]]],"f":[["(1)","Muslim, Abu Dawood, Tirmidhi, Nasa'ee and Ibn Maajah."],["(2)","Muslim."],["(3)","Nasa'ee."],["(4)","Targheeb wat Tarheeb (Vol.3 Pg.98)."]]},{"b":[["n",[["حضرت سعد بن ابی وقاصؓ","b"],[" فرماتے ہیں کہ وہ حضورؐ کے ساتھ ایک صحابی عورت کے پاس تشریف لے گئے اس کے سامنے کھجور کی گٹھلیاں یا کنکریاں رکھی ہوئی تھیں جن پر وہ تسبیح پڑھ رہی تھی۔ حضورؐ نے فرمایا میں تجھے ایسی چیز بتاؤں جو اس سے آسان ہو یا فرمایا جو اس سے افضل ہو",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ مَا خَلَقَ فِى ٱلسَّمَآءِ، سُبْحَانَ ٱللَّهِ عَدَدَ مَا خَلَقَ فِى ٱلْأَرْضِ، سُبْحَانَ ٱللَّهِ عَدَدَ مَا بَيْنَ ذَٰلِكَ، سُبْحَانَ ٱللَّهِ عَدَدَ مَا هُوَ خَالِقٌ، وَٱللَّهُ أَكْبَرُ مِثْلَ ذَٰلِكَ، وَٱلْحَمْدُ لِلَّهِ مِثْلَ ذَٰلِكَ، وَلَا إِلَٰهَ إِلَّا ٱللَّهُ مِثْلَ ذَٰلِكَ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ مِثْلَ ذَٰلِكَ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کی پاکی اس مخلوق کی تعداد کے برابر بیان کرتی ہوں جو اس نے آسمان میں پیدا کی اور اس مخلوق کے برابر جو اس نے زمین میں پیدا کی اور اس مخلوق کے برابر جو ان دونوں زمین و آسمان کے درمیان ہے اور اس مخلوق کے برابر جسے وہ پیدا کرنے والا ہے اور اس سب کے برابر ",""],["ٱللَّٰه","a"],[" اکبر اور اس سب کے برابر الحمد للہ اور اس سب کے برابر ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" اور اس سب کے برابر لا حول ولا قوۃ الا ب",""],["ٱللَّٰه","a"],["۔\"",""],[" (5)","s"]]]],"f":[["(5)","Abu Dawood, Tirmidhi, Nasa'ee, Ibn Hibbaan and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.99)."]]},{"b":[["n",[["حضرت ابوامامہؓ","b"],[" فرماتے ہیں کہ حضورؐ نے دیکھا کہ میں اپنے ہونٹوں کو ہلا رہا ہوں آپؐ نے پوچھا اے ابوامامہ! تم ہونٹ ہلا کر کیا پڑھ رہے ہو؟ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میں ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہا ہوں۔ حضورؐ نے فرمایا کیا میں تمہیں ایسا ذکر نہ بتاؤں جو تمہارے دن رات ذکر کرنے سے زیادہ بھی ہے اور افضل بھی ہے؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور بتائیں۔ فرمایا تم یہ کلمات کہا کرو",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ مَا خَلَقَ، سُبْحَانَ ٱللَّهِ مِلْأَ مَا خَلَقَ، سُبْحَانَ ٱللَّهِ عَدَدَ مَا فِى ٱلْأَرْضِ وَٱلسَّمَآءِ، سُبْحَانَ ٱللَّهِ مِلْأَ مَا فِى ٱلْأَرْضِ وَٱلسَّمَآءِ، سُبْحَانَ ٱللَّهِ عَدَدَ مَا أَحْصَىٰ كِتَابُهُ، سُبْحَانَ ٱللَّهِ مِلْأَ مَا أَحْصَىٰ كِتَابُهُ، سُبْحَانَ ٱللَّهِ عَدَدَ كُلِّ شَىْءٍ، سُبْحَانَ ٱللَّهِ مِلْأَ كُلِّ شَىْءٍ، وَٱلْحَمْدُ لِلَّهِ عَدَدَ مَا خَلَقَ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ مَا خَلَقَ، وَٱلْحَمْدُ لِلَّهِ عَدَدَ مَا فِى ٱلْأَرْضِ وَٱلسَّمَآءِ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ مَا فِى ٱلْأَرْضِ وَٱلسَّمَآءِ، وَٱلْحَمْدُ لِلَّهِ عَدَدَ مَا أَحْصَىٰ كِتَابُهُ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ مَا أَحْصَىٰ كِتَابُهُ، وَٱلْحَمْدُ لِلَّهِ عَدَدَ كُلِّ شَىْءٍ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ كُلِّ شَىْءٍ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کی پاکی بیان کرتا ہوں مخلوق کی تعداد کے برابر، ",""],["ٱللَّٰه","a"],[" کی پاکی مخلوق کے بھر دینے کے بقدر، ",""],["ٱللَّٰه","a"],[" کی پاکی ان تمام چیزوں کے برابر جو زمین و آسمان میں ہیں، ",""],["ٱللَّٰه","a"],[" کی پاکی ان تمام چیزوں کے بھر دینے کے بقدر جو زمین و آسمان میں ہیں، ",""],["ٱللَّٰه","a"],[" کی پاکی ان تمام چیزوں کی تعداد کے برابر جن کو اس کی کتاب نے شمار کیا، ",""],["ٱللَّٰه","a"],[" کی پاکی ان تمام چیزوں کو بھر دینے کے بقدر، ",""],["ٱللَّٰه","a"],[" کی پاکی ہر چیز کی تعداد کے برابر اور ",""],["ٱللَّٰه","a"],[" کی پاکی ہر چیز کو بھر دینے کے بقدر بیان کرتا ہوں۔ اسی طرح ",""],["ٱللَّٰه","a"],[" کی تعریف بیان کرتا ہوں (چاروں چیزوں کے شمار کرنے اور بھر دینے کے برابر)۔\" طبرانی میں یہ مضمون ہے کہ حضورؐ نے فرمایا کیا میں تمہیں ایسی زبردست چیز نہ بتاؤں کہ اس کے کہنے پر تمہیں اتنا زیادہ ثواب ملے گا کہ اگر تم دن رات عبادت کر کے تھک جاؤ تو بھی اس کے ثواب تک نہ پہنچ سکو؟ میں نے کہا ضرور بتائیں۔ آپؐ نے فرمایا \"الحمد للہ\" آخر تک لیکن یہ کلمات مختصر ہیں۔ پھر آپؐ نے فرمایا \"سبحان ",""],["ٱللَّٰه","a"],["\" اسی طرح سے اور \"",""],["ٱللَّٰه","a"],[" اکبر\" اسی طرح۔ طبرانی کی دوسری روایت میں یہ ہے کہ حضورؐ نے فرمایا ان کلمات کو سیکھ لو اور اپنے بعد اپنی اولاد کو سکھاؤ۔",""],[" (6)","s"],[" (7)","s"],[" (8)","s"]]]],"f":[["(6)","Ahmad, Ibn Abi Dunya, Nasa'ee, Ibn Khuzaymah, Ibn Hibbaan and Haakim."],["(7)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.99)."],["(8)","Tabraani. Haythami (Vol.10 Pg.93) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے دیکھا کہ میرے ہونٹ ہل رہے ہیں فرمایا اے ابوالدرداء! کیا پڑھ رہے ہو؟ میں نے کہا ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہا ہوں۔ آپؐ نے فرمایا کیا میں تمہیں ایسا ذکر نہ سکھاؤں جو رات کے شروع سے دن تک اور دن کے شروع سے رات تک مسلسل ذکر کرنے سے افضل ہے؟ میں نے کہا ضرور سکھائیں۔ فرمایا",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ مَا خَلَقَ، سُبْحَانَ ٱللَّهِ عَدَدَ كُلِّ شَىْءٍ، سُبْحَانَ ٱللَّهِ مِلْأَ مَا أَحْصَىٰ كِتَابُهُ، وَٱلْحَمْدُ لِلَّهِ عَدَدَ مَا خَلَقَ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ مَا خَلَقَ، وَٱلْحَمْدُ لِلَّهِ مِلْأَ مَا أَحْصَىٰ كِتَابُهُ","a"]]],["p",[["(ان کلمات کے معنی اوپر گزر چکے ہیں)",""],[" (9)","s"]]]],"f":[["(9)","Tabraani and Bazzaar. Haythami (Vol.10 Pg.94) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں میں ایک دن حلقہ میں حضورؐ کے ساتھ بیٹھا ہوا تھا اتنے میں ایک آدمی آیا اور اس نے حضورؐ اور لوگوں کو سلام کیا اور کہا السلام علیکم ورحمۃ ",""],["ٱللَّٰه","a"],["۔ حضورؐ نے جواب میں فرمایا علیکم السلام ورحمۃ ",""],["ٱللَّٰه","a"],[" وبرکاتہ۔ جب وہ آدمی بیٹھا تو اس نے کہا",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ كَمَا يُحِبُّ رَبُّنَا أَن يُحْمَدَ وَيَنْبَغِى لَهُۥ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کی ایسی تعریف کرتا ہوں جو بہت زیادہ ہو، عمدہ اور بابرکت ہو اور ایسی ہو جیسے ہمارے رب کو پسند ہے اور جیسی اس کی شان کے مناسب ہے۔\" حضورؐ نے اس سے فرمایا تم نے کیا کہا؟ اس نے دوبارہ یہی کلمات دہرا دیے۔ آپؐ نے فرمایا اس ذات کی قسم جس کے قبضے میں میری جان ہے! دس فرشتے ان کلمات کی طرف جھپٹے تھے ان میں سے ہر ایک انہیں لکھنا چاہتا تھا لیکن انہیں سمجھ نہ آیا کہ انہیں کیسے لکھیں، اس لیے وہ کلمات لے کر اوپر ",""],["ٱللَّٰه","a"],[" رب العزت کے دربار میں پہنچ گئے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا میرے بندے نے جیسے کہے ہیں ویسے ہی لکھ دو۔",""],[" (10)","s"]]]],"f":[["(10)","Ahmad, reporting from reliable sources as confirmed in Targheeb wat Tarheeb (Vol.3 Pg.103)."]]},{"b":[["n",[["حضرت ابوایوبؓ","b"],[" فرماتے ہیں حضورؐ کی مجلس میں ایک آدمی نے کہا",""]]],["q",[["ٱلْحَمْدُ لِلَّهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ تو حضورؐ نے پوچھا یہ کلمات کس نے کہے؟ وہ آدمی خاموش رہا اور یوں سمجھا کہ یہ کلمات جو اچانک اس کی زبان سے نکلے ہیں یہ حضورؐ کو ناگوار گزرے ہیں۔ حضورؐ نے پھر فرمایا وہ کون ہے؟ اس نے ٹھیک بات ہی کہی ہے۔ اس پر اس آدمی نے کہا میں نے کہے ہیں اور مجھے ان سے خیر کی امید ہے۔ فرمایا اس ذات کی قسم جس کے قبضے میں میری جان ہے! میں نے تیرہ فرشتوں کو دیکھا کہ وہ تمہارے ان کلمات کو اللہ کے دربار میں پیش کرنے کے لیے جھپٹ رہے ہیں۔","a"],[" (11)","s"]]]],"f":[["(11)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.102)."]]},{"b":[["n",[["حضرت سعید بن جبیرؒ","b"],[" کہتے ہیں حضرت عمرؓ نے دیکھا کہ ایک آدمی کے پاس تسبیح ہے جس پر وہ ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہا ہے۔ حضرت عمرؓ نے فرمایا تسبیح پر لمبے چوڑے ذکر کرنے کے بجائے اسے یہ کلمات کہنا کافی ہیں (کہ ان الفاظ کی تعداد کم ہے لیکن معنی بہت زیادہ ہیں) ",""]]],["q",[["سُبْحَانَ ٱللَّهِ مِلْءَ ٱلسَّمَٰوَٰتِ وَمِلْءَ مَا شَآءَ مِن شَىْءٍ بَعْدُ، وَٱلْحَمْدُ لِلَّهِ مِلْءَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمِلْءَ مَا شَآءَ مِن شَىْءٍ بَعْدُ، وَٱللَّهُ أَكْبَرُ مِلْءَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمِلْءَ مَا شَآءَ مِن شَىْءٍ بَعْدُ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کی اتنی پاکی بیان کرتا ہوں جو آسمانوں کو بھر دے اور آسمانوں کے بعد ",""],["ٱللَّٰه","a"],[" جس چیز کو چاہے اسے بھر دے۔ اور الحمد للہ اور ",""],["ٱللَّٰه","a"],[" اکبر بھی اسی طرح آسمانوں اور زمین کو بھر دینے کے بقدر اور اس کے بعد ",""],["ٱللَّٰه","a"],[" جس چیز کو چاہے اسے بھر دینے کے بقدر۔\"",""],[" (12)","s"]]]],"f":[["(12)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.210)."]]}]},"107":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ فقراء مہاجرین نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا کہ مالدار لوگ سارے بلند درجے لے اڑے اور ہمیشہ رہنے والی نعمتیں ان کے حصہ میں آ گئیں۔ حضورؐ نے فرمایا کیوں؟ عرض کیا جیسے ہم نماز پڑھتے ہیں ویسے یہ بھی پڑھتے ہیں۔ جیسے ہم روزہ رکھتے ہیں یہ بھی رکھتے ہیں لیکن یہ صدقہ خیرات کرتے ہیں ہم نہیں کر سکتے۔ یہ غلام آزاد کرتے ہیں ہم نہیں کر سکتے۔ حضورؐ نے فرمایا کیا میں تمہیں ایسی چیز نہ بتا دوں کہ تم اس پر عمل کر کے اپنے سے پہلوں کو پکڑ لو اور بعد والوں سے بھی آگے رہو اور کوئی شخص تم سے اس وقت تک افضل نہ ہو جب تک وہ بھی اس چیز کو نہ کر لے؟ صحابہؓ نے عرض کیا ضرور بتا دیجیے۔ ارشاد فرمایا کہ ہر نماز کے بعد سبحان ",""],["ٱللَّٰه","a"],["، ",""],["ٱللَّٰه","a"],[" اکبر، الحمد للہ ۳۳، ۳۳ مرتبہ پڑھ لیا کرو (ان حضرات نے شروع کر دیا مگر اس زمانہ کے مالدار بھی اسی نمونہ کے تھے انھوں نے بھی معلوم ہونے پر شروع کر دیا) تو فقراء مہاجرین دوبارہ حاضر ہوئے کہ یا رسول ",""],["ٱللَّٰه","a"],["! ہمارے مالدار بھائیوں نے بھی سن لیا اور وہ بھی یہی کرنے لگے۔ حضورؐ نے فرمایا یہ ",""],["ٱللَّٰه","a"],[" کا فضل ہے جسے چاہے عطا فرمائے۔ راوی ",""],["حضرت سمیؒ","b"],[" کہتے ہیں میں نے گھر والوں کو یہ حدیث سنائی تو انہوں نے مجھے کہا آپ کو سمجھنے میں غلطی ہو گئی ہے۔ آپ کے استاد نے یوں کہا ہوگا سبحان ",""],["ٱللَّٰه","a"],[" ۳۳، الحمد للہ ۳۳ مرتبہ اور ",""],["ٱللَّٰه","a"],[" اکبر ۳۴ مرتبہ پڑھا کرو۔ اس پر میں (اپنے استاد) حضرت ابوصالحؒ کے پاس گیا اور گھر والوں کی بات انہیں بتائی۔ انھوں نے میرا ہاتھ پکڑ کر فرمایا ",""],["ٱللَّٰه","a"],[" اکبر و سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ ایک مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر و سبحان ",""],["ٱللَّٰه","a"],[" والحمد للہ دو مرتبہ اس طرح انھوں نے ۳۳ مرتبہ ان کلمات کو گنا (کہ ",""],["ٱللَّٰه","a"],[" اکبر بھی اس حدیث میں ۳۳ بار ہے ۳۴ نہیں)۔ ابوداؤد میں یہ روایت اس طرح ہے کہ حضرت ابوذرؓ فرماتے ہیں کہ انھوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مالدار تو سارا اجر و ثواب لے گئے۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا اور اس روایت میں یوں ہے کہ تم ہر نماز کے بعد ",""],["ٱللَّٰه","a"],[" اکبر ۳۳ مرتبہ، الحمد للہ ۳۳ اور سبحان ",""],["ٱللَّٰه","a"],[" ۳۳ مرتبہ کہا کرو اور ان کے آخر میں یہ کہا",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُۥ لَا شَرِيكَ لَهُۥ، لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کے لیے تمام تعریف ہے اور وہ ہر چیز پر قادر ہے۔\" جب تم سب یہ کچھ کہہ لو گے تو تمہارے سارے گناہ معاف ہو جائیں گے چاہے سمندر کی جھاگ کے برابر ہوں۔ ترمذی اور نسائی میں یہ روایت حضرت ابن عباسؓ سے منقول ہے اور اس میں یہ ہے کہ حضورؐ نے فقراء مہاجرین سے فرمایا جب تم نماز پڑھ چکو تو سبحان ",""],["ٱللَّٰه","a"],[" ۳۳ مرتبہ، الحمد للہ ۳۳ مرتبہ، ",""],["ٱللَّٰه","a"],[" اکبر ۳۴ مرتبہ کہہ لیا کرو۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Bukhaari and Muslim."],["(2)","Abu Dawood."]]},{"b":[["n",[["حضرت ام دردائؓ","b"],[" فرماتی ہیں حضرت ابوالدرداءؓ کے ہاں ایک مہمان آیا۔ حضرت ابوالدرداءؓ نے اس سے پوچھا کہ تم نے ٹھہرنا ہے تو ہم تمہاری سواری چرنے کے لیے بھیج دیں؟ اور اگر ابھی جانا ہے تو چارہ ساتھ کر دیں۔ اس نے کہا نہیں میں نے ابھی جانا ہے۔ فرمایا میں تمہیں ایسا عمدہ توشہ دوں گا کہ اگر اس سے بہتر توشہ مجھے ملتا تو میں تمہیں وہ دیتا۔ میں نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مالدار لوگ تو دنیا اور آخرت دونوں لے اڑے۔ ہم بھی نماز پڑھتے ہیں وہ بھی نماز پڑھتے ہیں، ہم بھی روزہ رکھتے ہیں وہ بھی رکھتے ہیں۔ وہ صدقہ دیتے ہیں ہم صدقہ نہیں دے سکتے۔ حضورؐ نے فرمایا کیا میں ایسا کام نہ بتاؤں کہ جب تم اسے کرو گے تو پہلے والوں میں سے کوئی تم سے آگے نہ نکل سکے گا اور بعد والوں میں سے کوئی تم کو پا نہ سکے گا، البتہ جو یہ عمل کر لے گا وہ تمہیں پا لے گا۔ ہر نماز کے بعد ۳۳ مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، ۳۳ مرتبہ الحمد للہ اور ۳۳ مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کرو۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, Bazzaar and Tabraani, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.100). Abdur Razzaaq has reported a similar narration with the addition that Hadhrat Abu Dardaa said to Rasulullaah \"...they also strive in Jihaad as we do and perform the Fardh salaahs.\""]]},{"b":[["n",[["حضرت قتادہؒ","b"],[" مرسلاً روایت کرتے ہیں کہ کچھ مسلمان فقراء نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مالدار تو سارا اجر و ثواب لے گئے۔ وہ صدقہ کرتے ہیں ہم نہیں کر سکتے وہ خرچ کرتے ہیں ہم نہیں کر سکتے۔ حضورؐ نے فرمایا ذرا یہ بتاؤ اگر دنیا کا سارا مال ایک دوسرے پر رکھا جائے تو کیا یہ آسمان تک پہنچ جائے گا؟ انہوں نے کہا نہیں یا رسول ",""],["ٱللَّٰه","a"],["! فرمایا کیا میں تمہیں ایسی چیز نہ بتاؤں جس کی جڑ زمین میں ہے اور اس کی شاخ آسمان میں؟ ہر نماز کے بعد \"",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" و ",""],["ٱللَّٰه","a"],[" اکبر و سبحان ",""],["ٱللَّٰه","a"],[" و الحمد للہ\" دس مرتبہ کہا کرو۔ ان کلمات کی جڑ زمین اور شاخ آسمان میں ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Abdur Razzaaq and Ibn Zanjway, as quoted in Kanzul Ummaal (Vol.1 Pg.297)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں جب حضورؐ نے مجھ سے حضرت فاطمہؓ کی شادی کی تو ان کے ساتھ ایک چادر، چمڑے کا ایک گدا جس میں کھجور کی چھال بھری ہوئی تھی، دو چکیاں، ایک مشکیزہ اور دو گھڑے بھیجے۔ میں نے ایک دن حضرت فاطمہؓ سے کہا کنویں سے ڈول کھینچتے کھینچتے میرے سینے میں تکلیف شروع ہو گئی ہے اور تمہارے والد محترم کے پاس ",""],["ٱللَّٰه","a"],[" نے قیدی بھیجے ہیں، جاؤ اور ان سے خادم مانگ لاؤ۔ حضرت فاطمہؓ نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے بھی اتنی چکی پیسی ہے کہ میرے ہاتھوں میں گٹے پڑ گئے ہیں۔ چنانچہ وہ حضورؐ کی خدمت میں گئیں۔ حضورؐ نے فرمایا اے بیٹی! کیسے آئی ہو؟ حضرت فاطمہؓ نے کہا بس آپ کو سلام کرنے آئی ہوں اور شرم کی وجہ سے غلام نہ مانگ سکیں اور یوں ہی واپس آ گئیں۔ میں نے ان سے پوچھا کیا ہوا؟ انہوں نے کہا میں شرم کی وجہ سے غلام نہ مانگ سکی۔ پھر ہم دونوں اکٹھے حضورؐ کی خدمت میں گئے اور میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کنویں سے پانی کھینچتے کھینچتے میرے سینے میں تکلیف ہو گئی ہے۔ حضرت فاطمہؓ نے کہا چکی پیستے پیستے میرے ہاتھوں میں گٹے پڑ گئے ہیں۔ اب ",""],["ٱللَّٰه","a"],[" نے آپ کے پاس قیدی بھیجے ہیں اور کچھ وسعت عطا فرمائی ہے اس لیے ہمیں بھی ایک خادم دے دیں۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! صفہ والے سخت فقر و فاقہ میں ہیں اور بھوک کے مارے ان کا برا حال ہے، ان پر خرچ کرنے کے لیے میرے پاس اور کچھ نہیں ہے، اس لیے یہ غلام بیچ کر میں ساری رقم ان پر خرچ کروں گا، اس لیے میں تمہیں کوئی خادم نہیں دے سکتا۔ ہم دونوں واپس آ گئے۔ ہمارا ایک چھوٹا سا کمبل تھا جب اس سے سر ڈھانکتے تو پاؤں کھل جاتے اور جب پاؤں ڈھانکتے تو سر کھل جاتا۔ رات کو ہم دونوں اس میں لیٹے ہوئے تھے کہ اچانک حضورؐ ہمارے پاس تشریف لے آئے۔ ہم دونوں اٹھنے لگے تو فرمایا اپنی جگہ لیٹے رہو۔ پھر فرمایا تم نے مجھ سے جو خادم مانگا ہے کیا میں تمہیں اس سے بہتر چیز نہ بتاؤں؟ ہم نے کہا ضرور بتا دیں۔ فرمایا یہ چند کلمات مجھے حضرت جبرئیلؑ نے سکھائے ہیں کہ تم دونوں ہر نماز کے بعد دس مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، دس مرتبہ الحمد للہ، دس مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کرو اور جب بستر پر لیٹا کرو تو ۳۳ مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، ۳۳ مرتبہ الحمد للہ اور ۳۴ مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کرو۔ پھر حضرت علیؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! جب سے میں نے یہ تسبیحات حضورؐ سے سنی ہیں کبھی نہیں چھوڑیں۔ راوی کہتے ہیں ابن کواء نے حضرت علیؓ سے پوچھا کیا جنگ صفین کی رات کو بھی نہیں چھوڑیں؟ فرمایا اے عراق والو! ",""],["ٱللَّٰه","a"],[" تمہیں مارے، جنگ صفین کی رات کو بھی نہیں چھوڑیں۔ ابن ابی شیبہ میں حضرت علیؓ کی یہی حدیث اس طرح سے ہے کہ حضورؐ نے فرمایا کیا میں تم دونوں کو ایسی چیز نہ بتاؤں جو تمہارے لیے خادم سے بھی بہتر ہے؟ تم دونوں ہر نماز کے بعد ۳۳ مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، ۳۳ مرتبہ الحمد للہ اور ۳۴ مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کرو۔ اس طرح یہ سو ہو جائیں گے اور جب رات کو بستر پر لیٹا کرو تو بھی یہی کلمات کہا کرو۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ahmad, Bukhaari, Muslim, Abu Dawood and Tirmidhi, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.112). Ibn Sa'd (Vol.8 Pg.25) has reported a similar narration. Humaydi, Ibn Abi Shaybah, Abdur Razzaaq, Adani, Ibn Jareer, Haakim and others have also reported similar narrations, as have Nasa'ee and Ibn Maajah in brief, as quoted in Kanzul Ummaal (Vol.8 Pg.66)."],["(6)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں حضرت فاطمہؓ گھر کے کام کاج کی شکایت کرنے حضورؐ کی خدمت میں آئیں اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! چکی پیسنے کی وجہ سے میرے ہاتھوں میں گٹے پڑ گئے ہیں، خود ہی چکی پیستی ہوں، خود ہی آٹا گوندھتی ہوں۔ حضورؐ نے فرمایا اگر ",""],["ٱللَّٰه","a"],[" تمہیں کوئی چیز دینا چاہتے ہیں تو وہ تمہارے پاس خود ہی آ جائے گی لیکن میں تمہیں اس سے بہتر چیز بتاؤں گا۔ جب تم بستر پر لیٹا کرو تو ۳۳ مرتبہ سبحان ",""],["ٱللَّٰه","a"],["، ۳۳ مرتبہ الحمد للہ اور ۳۴ مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر کہا کرو، اس طرح یہ کلمات سو ہو جائیں گے اور یہ تمہارے لیے خادم سے بہتر ہیں۔ صبح کی نماز کے بعد اور مغرب کی نماز کے بعد دس دس مرتبہ یہ کلمات کہا کرو",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُۥ لَا شَرِيكَ لَهُۥ، لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ يُحْيِي وَيُمِيتُ بِيَدِهِ ٱلْخَيْرُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں، اسی کی بادشاہی ہے اور اسی کے لیے تمام تعریف ہے، وہی زندہ کرتا ہے اور مارتا ہے، اسی کے ہاتھ میں خیر ہے اور وہ ہر چیز پر قادر ہے۔\" ان میں سے ہر کلمہ کے بدلے میں دس نیکیاں لکھی جائیں گی اور دس گناہ گرائے جائیں گے اور ان میں سے ہر کلمہ کا ثواب اتنا ہوگا جتنا اولاد اسماعیل علیہ السلام میں سے ایک غلام آزاد کرنے کا اور اس دن کا شرک کے علاوہ ہر گناہ معاف کر دیا جائے گا۔ اور جب تم صبح کو ان کلمات کو کہہ لو گی تو شام کو کہنے تک ہر شیطان سے اور ہر بری حالت سے ان کلمات کی وجہ سے تمہاری حفاظت ہو گی۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad and Tabraani in brief, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.108)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں جب حضورؐ نماز پڑھ لیتے تو ان کلمات کو فرماتے",""]]],["q",[["لَا إِلَٰهَ إِلَّا ٱللَّهُ وَحْدَهُۥ لَا شَرِيكَ لَهُۥ، لَهُ ٱلْمُلْكُ وَلَهُ ٱلْحَمْدُ يُحْيِي وَيُمِيتُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ، ٱللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا رَادَّ لِمَا قَضَيْتَ وَلَا يَنْفَعُ ذَا ٱلْجَدِّ مِنْكَ ٱلْجَدُّ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں وہ اکیلا ہے اس کا کوئی شریک نہیں، (سارا) ملک اسی کا ہے اور ساری تعریفیں اسی کے لیے ہیں، وہی زندہ کرتا ہے اور مارتا ہے اور وہی ہر چیز پر قادر ہے۔ اے ",""],["ٱللَّٰه","a"],["! جو نعمت تو دے اسے کوئی روکنے والا نہیں اور جو تو روک لے اسے کوئی دینے والا نہیں اور جو فیصلہ تو کر دے اسے کوئی ٹالنے والا نہیں اور تیرے سامنے کسی مالدار کو اس کی دولت کام نہیں دیتی۔\"",""],[" (8)","s"]]]],"f":[["(8)","Bazzaar, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.103). Another narration of Bazzaar from Hadhrat Abdullaah bin Abbaas states that Rasulullaah used to recite these words after turning around from salaah. Tabraani has reported narrations with slight variations in the words, including one from Hadhrat Mughiera, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.103)."]]}]},"108":{"lead":[],"stories":[{"b":[["n",[["بنو ہاشم کے آزاد کردہ غلام ",""],["عبدالحمید","b"],[" کی والدہ حضورؐ کی ایک صاحبزادی کی خدمت کیا کرتی تھیں۔ انہوں نے اپنے بیٹے کو بتایا کہ حضورؐ کی صاحبزادی نے مجھے بتایا کہ نبی کریمؐ مجھے سکھایا کرتے تھے اور فرمایا کرتے تھے صبح کو یہ کلمات کہو",""]]],["q",[["سُبْحَانَ ٱللَّهِ وَبِحَمْدِهِ لَا قُوَّةَ إِلَّا بِٱللَّهِ مَا شَاءَ ٱللَّهُ كَانَ وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، أَعْلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ وَأَنَّ ٱللَّهَ قَدْ أَحَاطَ بِكُلِّ شَىْءٍ عِلْمًا","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" کی پاکی اور اس کی تعریف بیان کرتی ہوں، نیکیاں کرنے کی طاقت صرف ",""],["ٱللَّٰه","a"],[" ہی سے ملتی ہے۔ جو ",""],["ٱللَّٰه","a"],[" نے چاہا وہی ہوا اور جو نہیں چاہا وہ نہیں ہوا۔ میں جانتی ہوں کہ ",""],["ٱللَّٰه","a"],[" ہر چیز پر قادر ہے اور ",""],["ٱللَّٰه","a"],[" کے علم نے ہر چیز کو گھیرا ہوا ہے۔\" جو ان کلمات کو صبح کہے گا وہ شام تک محفوظ رہے گا اور جو شام کو کہے گا وہ صبح تک محفوظ رہے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood, Nasa'ee and Ibnus Sunni, as quoted in Tuhfatudh Dhaakireen (Pg.66)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا جو آدمی صبح و شام یہ کلمات سات مرتبہ کہے گا",""]]],["q",[["حَسْبِيَ ٱللَّهُ لَا إِلَٰهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" مجھے کافی ہے، اس کے سوا کوئی معبود نہیں، اسی پر میں نے توکل کیا، وہ عظیم عرش کا رب ہے۔\" ",""],["ٱللَّٰه","a"],[" تعالیٰ ہر فکر و پریشانی سے اس کی کفایت کریں گے چاہے سچے دل سے کہے یا جھوٹے سے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood."]]}]},"109":{"lead":[],"stories":[{"b":[["n",[["حضرت عصمہؓ","b"],[" فرماتے ہیں حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ کا سب سے زیادہ پسندیدہ عمل سجۃ الحدیث ہے اور ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ ناپسندیدہ عمل تحریف ہے۔ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! سجۃ الحدیث کیا ہے؟ فرمایا سجۃ الحدیث یہ ہے کہ لوگ باتیں کر رہے ہوں اور ایک آدمی تسبیح و تہلیل اور ",""],["ٱللَّٰه","a"],[" کا ذکر کر رہا ہو۔ پھر ہم نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! تحریف کیا ہے؟ آپؐ نے فرمایا تحریف یہ ہے کہ لوگ خیریت سے ہوں، اچھے حال پر ہوں اور کوئی پڑوسی یا ساتھی پوچھے تو یوں کہہ دیں کہ ہم برے حال میں ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.193). Haythami (Vol.10 Pg.81) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوادریس خولانیؒ","b"],[" کہتے ہیں حضرت معاذؓ نے فرمایا تم لوگوں کے ساتھ بیٹھتے ہو تو وہ لوگ لا محالہ باتیں شروع کر دیں گے، جب تم دیکھو کہ وہ (",""],["ٱللَّٰه","a"],[" سے) غافل ہو گئے ہیں تو تم اس وقت اپنے رب کی طرف پورے ذوق شوق سے متوجہ ہو جانا۔ ولید راوی کہتے ہیں حضرت عبدالرحمٰن بن یزید بن جابرؒ سے اس حدیث کا ذکر کیا گیا تو انہوں نے کہا یہ بات ٹھیک ہے اور مجھے حضرت ابوطلحہ حکیم بن دینارؒ نے بتایا کہ صحابہ کرامؓ کہا کرتے تھے کہ مقبول دعا کی نشانی یہ ہے کہ جب تم لوگوں کو غافل دیکھو تو اس وقت تم اپنے رب کی طرف متوجہ ہو جاؤ۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.236)."]]},{"b":[["n",[["حضرت ابوقلابہؒ","b"],[" فرماتے ہیں بازار میں دو آدمیوں کی آپس میں ملاقات ہوئی۔ ایک نے دوسرے سے کہا لوگ اس وقت (",""],["ٱللَّٰه","a"],[" سے) غافل ہیں، آؤ ہم ",""],["ٱللَّٰه","a"],[" سے استغفار کریں۔ چنانچہ دونوں نے ایسا کیا، پھر دونوں میں سے ایک کا انتقال ہو گیا۔ دوسرے نے اسے خواب میں دیکھا تو اس نے کہا تمہیں معلوم ہے کہ جب شام کو بازار میں ہماری ملاقات ہوئی تھی تو ",""],["ٱللَّٰه","a"],[" نے اس وقت ہماری مغفرت کر دی تھی۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Dunya and others, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.191)."]]}]},"110":{"lead":[],"stories":[{"b":[["n",[["حضرت ابولاس خزاعیؓ","b"],[" فرماتے ہیں حضورؐ نے ہمیں سفر حج کے لیے صدقہ کے اونٹ دیے۔ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہمارا خیال ہے کہ یہ اونٹ ہمیں اٹھا نہیں سکیں گے۔ فرمایا ہر اونٹ کے کوہان پر ایک شیطان ہوتا ہے، جب تم ان پر سوار ہونے لگو تو جیسے ",""],["ٱللَّٰه","a"],[" نے تمہیں حکم دے رکھا ہے تم ",""],["ٱللَّٰه","a"],[" کا نام لو پھر انہیں اپنے کام میں لاؤ، ان سے اپنی خدمت لو، یہ تمہیں ",""],["ٱللَّٰه","a"],[" کے حکم سے اٹھا لیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Tabraani. Haythami (Vol.10 Pg.131) has commented on the chain of narrators. Mention is also made of the narration in Isaabah (Vol.4 Pg.168)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں حضورؐ نے مجھے سواری پر اپنے پیچھے بٹھایا۔ جب آپؐ سواری پر ٹھیک طرح سے بیٹھ گئے تو آپؐ نے ۳ مرتبہ ",""],["ٱللَّٰه","a"],[" اکبر، ۳ مرتبہ سبحان ",""],["ٱللَّٰه","a"],[" اور ایک مرتبہ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہا، پھر میری طرف متوجہ ہو کر فرمایا جو بھی آدمی اپنی سواری پر سوار ہو کر وہ کام کرے جو میں نے کیے ہیں تو ",""],["ٱللَّٰه","a"],[" اس کی طرف متوجہ ہو کر ایسے ہی مسکرائیں گے جیسے میں تمہیں دیکھ کر مسکرایا ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad. Haythami (Vol.10 Pg.131) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوملیح بن اسامہؒ","b"],[" کہتے ہیں کہ میرے والد حضرت اسامہؓ نے فرمایا میں سواری پر حضورؐ کے پیچھے بیٹھا ہوا تھا کہ اتنے میں ہمارے اونٹ کو ٹھوکر لگی، میں نے کہا شیطان ہلاک ہو۔ حضورؐ نے فرمایا یہ مت کہو کہ شیطان ہلاک ہو کیونکہ اس سے تو وہ پھول کر گھر جتنا ہو جائے گا (یوں کہے گا کہ یہ مجھے کچھ سمجھتا ہے تبھی تو مجھے برا کہا) اور کہے گا میری طاقت سے ایسا ہوا، بلکہ یوں کہو بسم ",""],["ٱللَّٰه","a"],["، اس سے وہ مکھی کی طرح چھوٹا ہو جائے گا۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani. Haythami (Vol.10 Pg.132) has commented on the chain of narrators. Ahmad has reported a similar narration from Hadhrat Abu Tameemah Hujaymi, reporting from reliable sources."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ جب کسی اونچی جگہ پر چڑھتے تو یہ دعا پڑھتے",""]]],["q",[["ٱللَّهُمَّ لَكَ ٱلشَّرَفُ عَلَىٰ كُلِّ شَرَفٍ وَلَكَ ٱلْحَمْدُ عَلَىٰ كُلِّ حَالٍ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! ہر اونچی جگہ پر تیرے لیے بلندی ہے اور ہر حال میں تیرے لیے تمام تعریفیں ہیں۔\"",""],[" (4)","s"]]]],"f":[["(4)","Ahmad and Abu Ya'la. Haythami (Vol.10 Pg.133) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں جب ہم کسی منزل پر اترتے تو کجاووں کے کھولنے تک سبحان ",""],["ٱللَّٰه","a"],[" پڑھتے رہتے۔ سفر جہاد میں ",""],["ٱللَّٰه","a"],[" کا ذکر کرنے کے عنوان میں اس باب کے کچھ قصے گزر چکے ہیں۔",""]]]],"f":[]},{"b":[["n",[["حضرت عوفؒ","b"],[" کہتے ہیں جب حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ اپنے گھر سے نکلتے تو یہ دعا پڑھتے",""]]],["q",[["بِسْمِ ٱللَّهِ تَوَكَّلْتُ عَلَى ٱللَّهِ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِٱللَّهِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کے نام سے نکلتا ہوں، میں نے ",""],["ٱللَّٰه","a"],[" پر توکل کیا، گناہوں سے بچنے کی طاقت اور نیکی کرنے کی قوت صرف ",""],["ٱللَّٰه","a"],[" ہی سے ملتی ہے۔\" حضرت محمد بن کعب قرظیؒ کہتے ہیں یہ دعا تو قرآن میں بھی ہے (سورت ہود آیت ۴۱)",""]]],["q",[["وَقَالَ ٱرْكَبُوا۟ فِيهَا بِسْمِ ٱللَّهِ مَجْرٰىهَا وَمُرْسٰىهَا","a"]]],["p",[["ترجمہ: \"اس کشتی میں سوار ہو جاؤ، اس کا چلنا اور اس کا ٹھہرنا ",""],["ٱللَّٰه","a"],[" ہی کے نام سے ہے۔\" اور انہوں نے \"علی ",""],["ٱللَّٰه","a"],[" توکلنا\" کے الفاظ بیان کیے۔",""],[" (5)","s"]]]],"f":[["(5)","Tabraani in his Awsat, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.133)."]]}]},"111":{"lead":[],"stories":[{"b":[["n",[["حضرت ابی بن کعبؓ","b"],[" فرماتے ہیں حضورؐ کی عادت شریفہ یہ تھی کہ جب رات کا دو تہائی حصہ گزر جاتا تو آپؐ کھڑے ہو جاتے اور فرماتے اے لوگو! ",""],["ٱللَّٰه","a"],[" کا ذکر کرو، ",""],["ٱللَّٰه","a"],[" کا ذکر کرو۔ ہلا دینے والی چیز آ گئی (مراد پہلی مرتبہ صور پھونکنا ہے) جس کے بعد ایک پیچھے آنے والی چیز آئے گی (مراد دوسری مرتبہ صور پھونکنا ہے)، موت اپنے اندر لی ہوئی مصیبتوں کے ساتھ آ گئی ہے۔ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں آپ پر درود شریف کثرت سے پڑھنا چاہتا ہوں تو میں نے ذکر و دعا کے لیے جتنا وقت مقرر کر رکھا ہے اس میں سے کتنا وقت آپ پر درود پڑھنے کے لیے مقرر کر دوں؟ فرمایا جتنا تم چاہو۔ میں نے کہا چوتھائی وقت مقرر کر دوں؟ فرمایا جتنا تم چاہو لیکن اگر اس سے بڑھا دو تو بہتر ہے۔ میں نے کہا دو تہائی کر دوں؟ فرمایا جتنا تم چاہو لیکن اگر بڑھا دو تو بہتر ہے۔ میں نے کہا پھر تو میں سارا وقت ہی آپ کے لیے کر دیتا ہوں۔ فرمایا پھر تو تمہاری ہر فکر کی کفایت کی جائے گی اور تمہارا ہر گناہ معاف کر دیا جائے گا۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Tabraani. Haythami (Vol.10 Pg.129) has commented on the chain of narrators."],["(2)","Ahmad, Ibn Munee, Rooyaani, Haakim, Bayhaqi, Sa'eed bin Mansoor and Abd bin Humayd, as quoted in Kanzul Ummaal (Vol.1 Pg.215). Tirmidhi and Tabraani have reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.161). Abu Nu'aym has also reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.215)."]]},{"b":[["n",[["حضرت عبدالرحمٰن بن عوفؓ","b"],[" فرماتے ہیں ہم میں سے یعنی نبی کریمؐ کے صحابہؓ میں سے چار پانچ صحابیؓ دن رات حضورؐ کے ساتھ رہا کرتے تھے، کبھی آپؐ سے جدا نہیں ہوتے تھے تاکہ آپؐ کو جو ضرورت پیش آئے اس میں کام آ سکیں۔ چنانچہ ایک دن میں آپؐ کی خدمت میں آیا تو آپؐ کہیں تشریف لے جا رہے تھے۔ میں بھی آپؐ کے پیچھے ہو لیا۔ آپؐ رؤساء انصار کے ایک باغ میں تشریف لے گئے اور نماز شروع کر دی اور سجدہ فرمایا اور بہت لمبا سجدہ کیا یہاں تک کہ میں رونے لگ پڑا۔ میں سمجھا ",""],["ٱللَّٰه","a"],[" نے آپؐ کی روح قبض کر لی ہے، پھر آپؐ نے سر اٹھایا، مجھے بلایا اور فرمایا تمہیں کیا ہوا؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ نے بہت لمبا سجدہ کیا جس کی وجہ سے مجھے اندیشہ ہوا کہ شاید ",""],["ٱللَّٰه","a"],[" نے اپنے رسولؐ کی روح قبض کر لی ہے اور اب میں آپؐ کو کبھی بھی زندہ نہ دیکھ سکوں گا۔ آپؐ نے فرمایا میرے رب نے مجھ پر میری امت کے بارے میں ایک خاص فضل فرمایا ہے، اس کے شکرانے میں میں نے اتنا لمبا سجدہ کیا اور وہ یہ ہے کہ میری امت میں سے جو مجھ پر ایک مرتبہ درود بھیجے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے دس نیکیاں لکھیں گے اور اس کی دس برائیاں مٹا دیں گے۔ احمد اور حاکم کی روایت میں یہ ہے کہ حضورؐ نے فرمایا حضرت جبرئیلؑ نے مجھے کہا کیا میں آپ کو خوشخبری نہ سناؤں؟ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرما رہے ہیں کہ جو آپ پر درود بھیجے گا میں اس پر رحمت نازل کروں گا اور جو آپ پر سلام بھیجے گا میں اس پر سلام بھیجوں گا۔ اس لیے میں نے شکرانے میں ",""],["ٱللَّٰه","a"],[" کے لیے اتنا لمبا سجدہ کیا۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Abu Ya'la and Ibn Abi Dunya."],["(4)","Ahmad and Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.155). Haythami (Vol.10 Pg.161) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوطلحہ انصاریؓ","b"],[" فرماتے ہیں ایک دن حضورؐ بہت خوش تھے اور خوشی کے آثار آپؐ کے چہرے پر نظر آ رہے تھے۔ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آج تو آپ بہت ہی خوش ہیں اور خوشی کے آثار آپؐ کے چہرے پر نظر آ رہے ہیں۔ فرمایا جی ہاں! میرے پاس میرے رب کی طرف سے ایک فرشتہ آیا اور اس نے کہا آپ کی امت میں سے جو آپ پر ایک مرتبہ درود بھیجے گا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے دس نیکیاں لکھیں گے اور اس کی دس برائیاں مٹا دیں گے اور اس کے دس درجے بلند کر دیں گے اور جواب میں اس پر اتنی ہی رحمت نازل کریں گے۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad and Nasa'ee, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.157). Abdur Razzaaq has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.216). There are many variations of this Hadith narrated by many people."]]},{"b":[["n",[["حضرت کعب بن عجرہؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ نے فرمایا منبر کے قریب ہو جاؤ، ہم لوگ حاضر ہو گئے۔ جب حضورؐ نے منبر کے پہلے درجہ پر قدم مبارک رکھا تو فرمایا آمین، جب دوسرے پر قدم رکھا تو پھر فرمایا آمین، جب تیسرے پر قدم رکھا تو پھر فرمایا آمین۔ جب آپؐ فارغ ہو کر نیچے اترے تو ہم نے عرض کیا کہ ہم نے آج آپ سے (منبر پر چڑھتے ہوئے) ایسی بات سنی جو پہلے کبھی نہیں سنی تھی۔ آپؐ نے فرمایا کہ اس وقت حضرت جبرئیلؑ میرے سامنے آئے تھے (جب میں نے پہلے درجہ پر قدم رکھا تو) انہوں نے کہا ہلاک ہو وہ شخص جس نے رمضان کا مبارک مہینہ پایا پھر بھی اس کی مغفرت نہ ہوئی ہو۔ میں نے کہا آمین۔ پھر جب میں دوسرے درجہ پر چڑھا تو انہوں نے کہا ہلاک ہو وہ شخص جس کے سامنے آپؐ کا ذکر مبارک ہو اور وہ درود نہ بھیجے۔ میں نے کہا آمین۔ جب میں تیسرے درجے پر چڑھا تو انہوں نے کہا ہلاک ہو وہ شخص جس کے سامنے اس کے والدین یا ان میں سے کوئی ایک بڑھاپے کو پائیں اور وہ اس کو جنت میں داخل نہ کرائیں۔ میں نے کہا آمین۔",""],[" (6)","s"]]]],"f":[["(6)","Haakim. Ibn Hibbaan, Bazzaar, Ibn Khuzaymah and Tabraani have all reported similar narrations from various Sahabah, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.166). Haythami (Vol.10 Pg.166) has commented on some of the chains of narrators."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں ایک دن میں باہر آیا اور حضورؐ کی خدمت میں حاضر ہوا۔ آپؐ نے فرمایا کیا میں تمہیں لوگوں میں سب سے زیادہ بخیل آدمی نہ بتاؤں؟ صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور بتائیں۔ فرمایا جس کے سامنے میرا ذکر ہو اور وہ مجھ پر درود نہ بھیجے تو یہ لوگوں میں سب سے زیادہ بخیل آدمی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abu Aasim in his Kitaabus Salaah, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.170)."]]},{"b":[["n",[["حضرت ابومسعودؓ","b"],[" فرماتے ہیں حضورؐ ہمارے پاس تشریف لائے اور ہمارے ساتھ حضرت سعد بن عبادہؓ کی مجلس میں بیٹھ گئے۔ حضرت نعمان بن بشیرؓ کے والد حضرت بشیر بن سعدؓ نے حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہمیں آپ پر درود پڑھنے کا حکم دیا ہے تو یا رسول ",""],["ٱللَّٰه","a"],["! آپ ہمیں بتائیں کہ ہم آپ پر کس طرح درود پڑھا کریں۔ حضورؐ نے سکوت فرمایا یہاں تک کہ ہم تمنا کرنے لگے کہ کاش وہ حضورؐ سے یہ بات نہ پوچھتے۔ پھر حضورؐ نے کچھ دیر کے بعد فرمایا یوں کہا کرو",""]]],["q",[["ٱللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَبَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ فِي ٱلْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! محمدؐ پر اور آل محمدؐ پر ایسے درود بھیج جیسے تو نے ابراہیمؑ پر درود بھیجا اور محمدؐ پر اور آل محمدؐ پر ایسے برکت نازل فرما جیسے تو نے ابراہیمؑ پر تمام جہانوں میں برکت نازل فرمائی۔ بے شک تو ہر تعریف کا مستحق اور بڑی شان والا ہے۔\" اور مجھ پر سلام پڑھنے کا طریقہ تمہیں (التحیات میں) معلوم ہو چکا ہے۔",""],[" (8)","s"]]]],"f":[["(8)","Maalik, Ibn Abi Shaybah, Muslim, Abu Dawood, Tirmidhi, Nasa'ee, Abdur Razzaaq and Abd bin Humayd, as quoted in Kanzul Ummaal (Vol.1 Pg.217)."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" نے فرمایا جب تم لوگ حضورؐ پر درود بھیجنے لگو تو اچھی طرح بھیجا کرو کیونکہ تمہیں پتہ نہیں ہے، تمہارا درود تو حضورؐ پر (فرشتوں کے ذریعہ) پیش کیا جاتا ہے۔ لوگوں نے عرض کیا آپ ہمیں سکھا دیں۔ فرمایا یوں کہا کرو",""]]],["q",[["ٱللَّهُمَّ ٱجْعَلْ صَلَوَاتِكَ وَرَحْمَتَكَ وَبَرَكَاتِكَ عَلَىٰ سَيِّدِ ٱلْمُرْسَلِينَ وَإِمَامِ ٱلْمُتَّقِينَ وَخَاتَمِ ٱلنَّبِيِّينَ مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ إِمَامِ ٱلْخَيْرِ وَقَائِدِ ٱلْخَيْرِ وَرَسُولِ ٱلرَّحْمَةِ، ٱللَّهُمَّ ٱبْعَثْهُ مَقَامًا مَحْمُودًا يَغْبِطُهُ بِهِ ٱلْأَوَّلُونَ وَٱلْآخِرُونَ","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! اپنی خاص رحمتیں، مہربانی اور اپنی برکتیں اس ذات کے حصے میں کر دے جو تمام رسولوں کے سردار، سب متقیوں کے امام اور آخری نبی ہیں، جن کا نام محمدؐ ہے، جو تیرے بندے اور رسول ہیں، جو خیر کے امام اور پیشوا ہیں اور رحمت والے رسول ہیں۔ اے ",""],["ٱللَّٰه","a"],["! ان کو اس مقام محمود میں اٹھا جس پر تمام اگلے پچھلے لوگ رشک کریں گے۔\"",""]]],["q",[["ٱللَّهُمَّ صَلِّ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا صَلَّيْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ، ٱللَّهُمَّ بَارِكْ عَلَىٰ مُحَمَّدٍ وَعَلَىٰ آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَىٰ إِبْرَاهِيمَ وَعَلَىٰ آلِ إِبْرَاهِيمَ إِنَّكَ حَمِيدٌ مَجِيدٌ","a"]]],["p",[["(ان کلمات کا ترجمہ اوپر گزر چکا ہے۔) حضرت علیؓ درود کے جو الفاظ سکھایا کرتے تھے وہ پہلے گزر چکے ہیں۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Maajah, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.165)."]]},{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" نے فرمایا جیسے پانی آگ کو مٹا دیتا ہے، حضورؐ پر درود بھیجنا اس سے زیادہ خطاؤں کو مٹانے والا ہے اور نبی کریمؐ پر سلام بھیجنا غلام آزاد کرنے سے افضل ہے اور حضورؐ کی محبت غلام آزاد کرنے سے اور ",""],["ٱللَّٰه","a"],[" کے راستے میں تلوار چلانے سے افضل ہے۔",""],[" (10)","s"]]]],"f":[["(10)","Khateeb and Isfahaani, as quoted in Kanzul Ummaal (Vol.1 Pg.213)."]]},{"b":[["n",[["حضرت عمر بن خطابؓ","b"],[" نے فرمایا جب تک تم اپنے نبیؐ پر درود نہیں بھیجتے اس وقت تک دعا آسمان اور زمین کے درمیان رکی رہتی ہے، بالکل اوپر نہیں جاتی۔",""],[" (11)","s"]]]],"f":[["(11)","Tirmidhi. Ibn Raahway has reported a similar narration."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے فرمایا جب تک نبی کریمؐ پر درود نہیں پڑھ لیا جاتا اس وقت تک دعا ساری کی ساری آسمان سے پہلے رکی رہتی ہے، جب درود آ جاتا ہے پھر دعا اوپر جاتی ہے۔",""],[" (12)","s"]]]],"f":[["(12)","Rahaawi. Haafidh Iraqi has stated that this narration, although appearing to be the words of Hadhrat Umar, must have come from Rasulullaah. Refer to Kanzul Ummaal (Vol.1 Pg.213) for details."]]},{"b":[["n",[["حضرت علیؓ","b"],[" نے فرمایا جب تک حضرت محمدؐ پر درود نہیں پڑھ لیا جاتا اس وقت تک ہر دعا رکی رہتی ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Tabraani in his Awsat, Bayhaqi, Ubaydullaah Eeshi and Rahaawi, as quoted in Kanzul Ummaal (Vol.1 Pg.214)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں جو آدمی جمعہ کے دن نبی کریمؐ پر سو دفعہ درود پڑھے گا وہ قیامت کے دن اس حال میں آئے گا کہ اس کے چہرے پر خاص قسم کا نور ہوگا جسے دیکھ کر لوگ کہیں گے یہ کون سا عمل کیا کرتا تھا؟ (جس کی وجہ سے اسے یہ نور ملا ہے۔)",""],[" (14)","s"]]]],"f":[["(14)","Bayhaqi, as quoted in Kanzul Ummaal (Vol.1 Pg.214)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا نبیوں کے علاوہ کسی اور پر درود بھیجنا مناسب نہیں۔",""],[" (15)","s"]]]],"f":[["(15)","Abdur Razzaaq, as quoted in Kanzul Ummaal (Vol.1 Pg.216)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا کسی کی طرف سے کسی پر درود بھیجنا مناسب نہیں، صرف نبی کریمؐ پر درود بھیجنا چاہیے۔",""],[" (16)","s"]]]],"f":[["(16)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.167)."]]}]},"112":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں ہم شمار کیا کرتے تھے کہ حضورؐ ایک ہی مجلس میں سو دفعہ یہ دعا کہہ لیتے",""]]],["q",[["رَبِّ ٱغْفِرْ لِي وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ ٱلتَّوَّابُ ٱلرَّحِيمُ","a"]]],["p",[["ترجمہ: \"اے میرے رب! میری مغفرت فرما، میری توبہ قبول فرما، بے شک تو ہی توبہ قبول کرنے والا اور نہایت مہربان ہے۔\"",""],[" (1)","s"]]]],"f":[["(1)","Abu Dawood and Tirmidhi."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں میں نے حضورؐ سے اپنی زبان کی تیزی کی شکایت کی۔ آپؐ نے فرمایا تم استغفار سے کہاں غفلت میں پڑے ہو؟ میں تو روزانہ ",""],["ٱللَّٰه","a"],[" سے سو مرتبہ استغفار کرتا ہوں۔ ابونعیم کی دوسری روایت میں حضرت حذیفہؓ فرماتے ہیں میں نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میری زبان گھر والوں کے بارے میں تیزی کر جاتی ہے جس سے مجھے ڈر ہے کہ یہ تو مجھے آگ میں داخل کر دے گی۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Nu'aym in his Hilya (Vol.1 Pg.276). Ibn Abi Shaybah has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں حضورؐ ایک سفر میں تھے۔ آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" سے استغفار کرو۔ ہم نے استغفار کیا۔ فرمایا پورے ستر مرتبہ کرو۔ ہم نے ستر مرتبہ کیا۔ فرمایا جو بندہ اور بندی ایک دن میں ستر مرتبہ ",""],["ٱللَّٰه","a"],[" سے استغفار کرے گا ",""],["ٱللَّٰه","a"],[" اس کے سات سو گناہ معاف کر دیں گے اور وہ بندہ اور بندی ناکام و نامراد ہو گیا جو دن اور رات میں سات سو سے زیادہ گناہ کرے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Nu'aym in his Hilya (Vol.1 Pg.276)."]]},{"b":[["n",[["حضرت علی بن ربیعہؒ","b"],[" کہتے ہیں مجھے حضرت علیؓ نے اپنے پیچھے بٹھایا اور حرہ کی طرف لے گئے، پھر آسمان کی طرف سر اٹھا کر فرمایا اے ",""],["ٱللَّٰه","a"],["! میرے گناہوں کو معاف فرما کیونکہ تیرے علاوہ اور کوئی بھی گناہوں کو معاف نہیں کرتا۔ پھر میری طرف متوجہ ہو کر مسکرانے لگے۔ میں نے کہا اے امیر المومنین! پہلے آپ نے اپنے رب سے استغفار کیا پھر میری طرف متوجہ ہو کر مسکرانے لگے، یہ کیا بات ہے؟ انہوں نے فرمایا حضورؐ نے ایک دن مجھے اپنے پیچھے بٹھایا تھا پھر مجھے حرہ کی طرف لے گئے تھے، پھر آسمان کی طرف سر اٹھا کر فرمایا اے ",""],["ٱللَّٰه","a"],["! میرے گناہوں کو معاف فرما کیونکہ تیرے علاوہ اور کوئی بھی گناہوں کو معاف نہیں کرتا، پھر میری طرف متوجہ ہو کر مسکرانے لگے۔ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! پہلے آپ نے اپنے رب سے استغفار کیا پھر میری طرف متوجہ ہو کر مسکرانے لگے ہیں، اس کی کیا وجہ ہے؟ فرمایا میں اس وجہ سے مسکرا رہا ہوں کہ میرا رب اپنے بندے پر تعجب کر کے مسکراتا ہے، اس بندے کو معلوم ہے کہ میرے علاوہ اور کوئی بھی گناہوں کو معاف نہیں کرتا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Dunya, Bayhaqi and Isfahaani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.131). Ibn Najjaar has reported a similar narration, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں میں نے حضورؐ کے بعد کسی کو آپؐ سے زیادہ یہ دعا",""]]],["q",[["أَسْتَغْفِرُ ٱللَّهَ وَأَتُوبُ إِلَيْهِ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں اور توبہ کر کے اسی کی طرف متوجہ ہوتا ہوں۔\" کہتے ہوئے نہیں دیکھا۔",""],[" (5)","s"],[" (6)","s"]]]],"f":[["(5)","Ibn Abi Shaybah and Ibn Munee, as quoted in Kanzul Ummaal (Vol.1 Pg.211)."],["(6)","Abu Ya'la and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت محمد بن عبد","b"],["ٱللَّٰه","a"],[" بن محمد بن جابر بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" اپنے والد حضرت عبد",""],["ٱللَّٰه","a"],["ؒ سے نقل کرتے ہیں، وہ اپنے دادا حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ سے روایت کرتے ہیں کہ ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر دو یا تین مرتبہ کہا ہائے میرے گناہ! ہائے میرے گناہ! حضورؐ نے فرمایا یہ کہو",""]]],["q",[["ٱللَّهُمَّ مَغْفِرَتُكَ أَوْسَعُ مِنْ ذُنُوبِي وَرَحْمَتُكَ أَرْجَىٰ عِنْدِي مِنْ عَمَلِي","a"]]],["p",[["ترجمہ: \"اے ",""],["ٱللَّٰه","a"],["! تیری مغفرت میرے گناہوں سے زیادہ وسعت والی ہے اور مجھے اپنے عمل سے زیادہ تیری رحمت کی امید ہے۔\" اس نے یہ کہا۔ حضورؐ نے کہا دوبارہ کہو۔ اس نے دوبارہ کہا۔ حضورؐ نے کہا پھر کہو۔ اس نے پھر کہا۔ حضورؐ نے کہا اٹھ جا، ",""],["ٱللَّٰه","a"],[" نے تیری مغفرت کر دی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.132)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" نے ایک آدمی کو یہ کہتے ہوئے سنا",""]]],["q",[["أَسْتَغْفِرُ ٱللَّهَ وَأَتُوبُ إِلَيْهِ","a"]]],["p",[["ترجمہ: \"میں ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں اور اس کے سامنے توبہ کرتا ہوں۔\" فرمایا تیرا بھلا ہو، اس کے پیچھے اس کی بہن کو بھی لے آ اور وہ یہ ہے",""]]],["q",[["فَٱغْفِرْ لِي وَتُبْ عَلَيَّ","a"]]],["p",[["ترجمہ: \"تو میری مغفرت کر دے اور میری توبہ قبول فرما۔\"",""],[" (8)","s"]]]],"f":[["(8)","Ahmad in his Zuhd, as quoted in Kanzul Ummaal (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں حضرت علیؓ نے فرمایا مجھے اس آدمی پر تعجب ہوتا ہے جو ہلاک ہو جائے حالانکہ نجات کا سامان اس کے پاس تھا۔ پوچھا گیا نجات کا سامان کیا ہے؟ فرمایا استغفار۔",""],[" (9)","s"]]]],"f":[["(9)","Deenowri, as quoted in Kanzul Ummaal (Vol.1 Pg.211)."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" نے فرمایا اس آدمی کے لیے خوشخبری ہے جس کے اعمال نامہ میں تھوڑا سا بھی استغفار پایا جائے۔",""],[" (10)","s"]]]],"f":[["(10)","Ibn Abi Shaybah, as quoted in Kanzul Ummaal (Vol.1 Pg.212)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا جو آدمی بھی تین مرتبہ یہ دعا پڑھے",""]]],["q",[["أَسْتَغْفِرُ ٱللَّهَ ٱلَّذِي لَا إِلَٰهَ إِلَّا هُوَ ٱلْحَيُّ ٱلْقَيُّومُ وَأَتُوبُ إِلَيْهِ","a"]]],["p",[["ترجمہ: \"میں اس ",""],["ٱللَّٰه","a"],[" سے مغفرت طلب کرتا ہوں جس کے سوا کوئی معبود نہیں، جو ہمیشہ زندہ رہنے والا اور سب کو قائم رکھنے والا ہے اور میں اس کے سامنے توبہ کرتا ہوں۔\" اس کی پوری مغفرت کر دی جائے گی اگرچہ وہ میدان جنگ سے بھاگ کر آیا ہو۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.210)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" نے فرمایا اگر تم لوگوں کو میرے گناہ معلوم ہو جائیں تو میرے پیچھے دو آدمی بھی نہ چلیں اور تم لوگ میرے سر پر مٹی ڈالنے لگو۔ اگر ",""],["ٱللَّٰه","a"],[" تعالیٰ میرے گناہوں میں سے ایک گناہ کو بھی معاف کر دے اور مجھے اس کے بدلے میں عبد",""],["ٱللَّٰه","a"],[" ابن روثہ (گوبر کا بیٹا عبد",""],["ٱللَّٰه","a"],[" کہہ کر) پکارا جائے تو بھی میں اس پر راضی ہوں۔",""],[" (12)","s"]]]],"f":[["(12)","Haakim (Vol.3 Pg.316), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" نے فرمایا میں روزانہ بارہ ہزار مرتبہ توبہ اور استغفار کرتا ہوں اور یہ مقدار میرے (گناہوں کے) قرضے کے مطابق ہے یا فرمایا اس کے (یعنی ",""],["ٱللَّٰه","a"],[" کے مجھ پر) قرضے کے مطابق ہے۔ ایک روایت میں یہ ہے کہ یہ میرے گناہوں کے برابر ہے۔",""],[" (13)","s"]]]],"f":[["(13)","Abu Nu'aym in his Hilya (Vol.1 Pg.383)."]]},{"b":[["n",[["ایک آدمی نے ",""],["حضرت براءؓ","b"],[" سے پوچھا کہ اے ابوعمارہ! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے",""]]],["q",[["وَلَا تُلْقُوا۟ بِأَيْدِيكُمْ إِلَى ٱلتَّهْلُكَةِ","a"]]],["p",[["ترجمہ: \"اپنے آپ کو اپنے ہاتھوں تباہی میں مت ڈالو۔\" (سورت بقرہ آیت ۱۹۵) کیا اس سے مراد وہ آدمی ہے جو دشمن سے اتنی جنگ کرتا ہے کہ خود شہید ہو جاتا ہے؟ آپؓ نے فرمایا نہیں بلکہ اس سے مراد وہ آدمی ہے جو گناہ کرے اور یوں کہے کہ ",""],["ٱللَّٰه","a"],[" اسے معاف نہیں کریں گے۔",""],[" (14)","s"]]]],"f":[["(14)","Haakim, reporting from reliable sources, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.132)."]]}]},"113":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا قیامت کے دن ",""],["ٱللَّٰه","a"],[" تعالیٰ بعض قوموں کا حشر ایسی طرح فرمائیں گے کہ ان کے چہروں میں نور چمکتا ہوا ہوگا، وہ موتیوں کے منبروں پر ہوں گے، لوگ ان پر رشک کرتے ہوں گے، وہ انبیاء اور شہداء نہیں ہوں گے۔ ایک دیہاتی نے گھٹنوں کے بل بیٹھ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان کا حال بیان کر دیجئے تاکہ ہم انہیں پہچان لیں۔ حضورؐ نے فرمایا یہ مختلف جگہوں کے اور مختلف خاندانوں کے وہ لوگ ہوں گے جو ",""],["ٱللَّٰه","a"],[" کی وجہ سے آپس میں محبت کریں اور ایک جگہ جمع ہو کر ",""],["ٱللَّٰه","a"],[" کے ذکر میں مشغول ہوں۔",""],[" (1)","s"]]]],"f":[["(1)","Tabraani."]]},{"b":[["n",[["حضرت عمرو بن عبسہؓ","b"],[" فرماتے ہیں میں نے حضورؐ کو فرماتے ہوئے سنا کہ رحمان کے دائیں طرف ایسے لوگ ہوں گے جو انبیاء اور شہداء نہیں ہوں گے۔ اور رحمان کے دونوں ہاتھ دائیں ہیں۔ ان کے چہروں کی سفیدی دیکھنے والوں کی نگاہ کو چکاچوند کر دے گی۔ ان کو جو مقام اور ",""],["ٱللَّٰه","a"],[" کا قرب نصیب ہوگا اسے انبیاء اور شہداء بہت اچھا سمجھیں گے۔ کسی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! یہ لوگ کون ہیں؟ آپؐ نے فرمایا یہ مختلف قبیلوں کے لوگ ہیں جو ",""],["ٱللَّٰه","a"],[" کے ذکر کی وجہ سے آپس میں جمع ہوں اور اچھی اچھی باتوں کو ایسے چن لیں جیسے کھجور کھانے والا اچھی کھجوریں چنتا ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Tabraani, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.66), reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.77)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضورؐ اپنے صحابہؓ کے پاس تشریف لائے، وہ آپس میں باتیں کر رہے تھے۔ ان لوگوں نے عرض کیا کہ ہم آپس میں زمانہ جاہلیت کے بارے میں بات کر رہے تھے کہ کس طرح ہم گمراہ تھے پھر کیسے ",""],["ٱللَّٰه","a"],[" نے ہمیں ہدایت عطا فرمائی۔ حضورؐ کو ان کا یہ عمل بہت پسند آیا۔ آپؐ نے فرمایا تم نے بہت اچھا کام کیا، اسی طرح رہا کرو اور اسی طرح کیا کرو۔",""],[" (3)","s"]]]],"f":[["(3)","Tabraani in his Awsat. Haythami (Vol.10 Pg.80) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" نے فرمایا حضرت عمرؓ کا تذکرہ کثرت سے کیا کرو کیونکہ جب حضرت عمرؓ کا ذکر ہوگا تو عدل و انصاف کا ذکر بھی ہوگا اور جب عدل و انصاف کا ذکر ہوگا تو ",""],["ٱللَّٰه","a"],[" کا ذکر ہوگا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.391)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" نے فرمایا نبی کریمؐ پر درود بھیجو اور حضرت عمر بن خطابؓ کا تذکرہ کر کے اپنی مجلسوں کو آراستہ کیا کرو۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.394)."]]}]},"114":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" کے ولی اور دوست کون لوگ ہیں؟ حضورؐ نے فرمایا جنہیں دیکھنے سے ",""],["ٱللَّٰه","a"],[" یاد آ جائے۔",""],[" (1)","s"]]]],"f":[["(1)","Bazzaar. Haythami (Vol.10 Pg.78) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت حنظلہ کاتب اسیدیؓ","b"],[" جو حضورؐ کے کاتبوں میں سے تھے فرماتے ہیں ہم لوگ حضورؐ کے پاس تھے، حضورؐ نے ہمارے سامنے جنت اور جہنم کا ذکر اس طرح فرمایا کہ گویا ہم دونوں کو آنکھوں سے دیکھ رہے ہیں۔ پھر میں اٹھ کر بیوی بچوں کے پاس چلا گیا اور ان کے ساتھ ہنسنے کھیلنے میں لگ گیا، پھر مجھے وہ حالت یاد آ گئی جو (حضورؐ کے سامنے) ہماری تھی (کہ دنیا بھولے ہوئے تھے اور جنت اور جہنم آنکھوں کے سامنے تھیں) تو میں گھر سے نکلا۔ آگے پوری حدیث ذکر کی جس طرح کہ جنت اور جہنم پر ایمان لانے کے عنوان میں گزر چکی ہے، اس کے آخر میں یہ ہے کہ آپؐ نے فرمایا اے حنظلہ! تمہاری جو حالت میرے پاس ہوتی ہے وہی حالت اگر گھر والوں کے پاس جا کر بھی رہے تو فرشتے تم سے بستروں پر اور راستوں میں مصافحہ کرنے لگیں، لیکن حنظلہ! بات یہ ہے کہ گاہے گاہے گاہے ہے۔ ایک روایت میں ہے کہ جیسے تم میرے پاس ہوتے ہو ایسے ہی گھر جا کر بھی رہو تو فرشتے تم پر پروں سے سایہ کریں۔",""],[" (2)","s"]]]],"f":[["(2)","Hasan bin Sufyaan and Abu Nu'aym."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب ہم آپ کے پاس ہوتے ہیں تو ہمارے دل نرم ہو جاتے ہیں اور دنیا کی بے رغبتی اور آخرت کی رغبت کی کیفیت بن جاتی ہے (لیکن جب ہم چلے جاتے ہیں تو پھر یہ کیفیت نہیں رہتی)۔ حضورؐ نے فرمایا میرے پاس تمہاری جو کیفیت ہوتی ہے اگر میرے پاس سے جانے کے بعد بھی وہی رہے تو فرشتے تمہاری زیارت کرنے آئیں اور راستوں میں تم سے مصافحہ کریں۔ اگر تم گناہ نہیں کرو گے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے لوگوں کو لے آئیں گے جو اتنے گناہ کریں گے کہ وہ آسمان کے بادلوں تک پہنچ جائیں گے، پھر وہ ",""],["ٱللَّٰه","a"],[" سے استغفار کریں گے تو ان کے جتنے گناہ ہوں گے ",""],["ٱللَّٰه","a"],[" ان سب کو معاف کر دیں گے اور کوئی پرواہ نہیں کریں گے۔",""],[" (3)","s"],[" (4)","s"]]]],"f":[["(3)","Tayaalisi, as quoted in Kanzul Ummaal (Vol.1 Pg.100)."],["(4)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.1 Pg.101)."]]},{"b":[["n",[["حضرت عروہ بن زبیرؓ","b"],[" فرماتے ہیں ہم لوگ طواف کر رہے تھے، میں نے طواف کے دوران حضرت عبد",""],["ٱللَّٰه","a"],[" بن عمرؓ کو ان کی بیٹی سے شادی کا پیغام دیا تو وہ خاموش رہے اور میرے پیغام کا کوئی جواب نہ دیا۔ میں نے کہا اگر یہ راضی ہوتے تو کوئی نہ کوئی جواب ضرور دیتے، اب ",""],["ٱللَّٰه","a"],[" کی قسم! میں ان سے اس بارے میں کوئی بات نہیں کروں گا۔ ",""],["ٱللَّٰه","a"],[" کی شان! وہ مجھ سے پہلے مدینہ واپس پہنچ گئے، میں بعد میں مدینہ آیا۔ چنانچہ میں حضورؐ کی مسجد میں داخل ہوا اور جا کر حضورؐ کو سلام کیا اور آپؐ کی شان کے مطابق آپؐ کا حق ادا کرنے کی کوشش کی۔ پھر حضرت ابن عمرؓ کی خدمت میں حاضر ہوا تو انہوں نے خوش آمدید کہا اور فرمایا کب آئے ہو؟ میں نے کہا ابھی پہنچا ہوں۔ انہوں نے فرمایا ہم لوگ طواف کر رہے تھے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کے اپنی آنکھوں کے سامنے ہونے کا دھیان جمائے ہوئے تھے، کیا اس وقت تم نے مجھ سے (میری بیٹی) حضرت سودہ بنت عبد",""],["ٱللَّٰه","a"],[" کا ذکر کیا تھا؟ حالانکہ تم مجھ سے اس بارے میں کسی اور جگہ بھی مل سکتے تھے۔ میں نے کہا ایسا ہونا مقدر تھا اس لیے ایسا ہو گیا۔ انہوں نے فرمایا اب تمہارا اس بارے میں کیا خیال ہے؟ میں نے کہا اب تو پہلے سے بھی زیادہ تقاضا ہے۔ چنانچہ انہوں نے دونوں بیٹوں حضرت سالم اور حضرت عبد",""],["ٱللَّٰه","a"],[" کو بلا کر میری شادی کر دی۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.309). Ibn Sa'd (Vol.4 Pg.167) has reported a similar narration."]]}]},"115":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں حضورؐ بتاتے تھے کہ جس نماز کے لیے مسواک کی جاتی ہے اسے اس نماز پر ستر گنا فضیلت حاصل ہے جس کے لیے مسواک نہ کی جائے اور آپؐ نے یہ بھی فرمایا ذکر خفی جسے کوئی نہ سنے اسے (بلند آواز والے ذکر پر) ستر گنا فضیلت حاصل ہے۔ اور فرماتے تھے جب قیامت کا دن آئے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ تمام مخلوقات کو حساب کے لیے جمع کریں گے اور لکھنے والے فرشتے اپنے لکھے ہوئے دفتر لے کر آئیں گے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ان فرشتوں سے فرمائیں گے کیا اس بندے کا کوئی عمل لکھنے سے رہ گیا ہے؟ وہ کہیں گے اے ہمارے رب! ہمیں اس کے جس عمل کا پتہ چلا وہ ہم نے ضرور لکھا ہے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ اس بندے سے کہیں گے تیرا ایک چھپا ہوا عمل میرے پاس ہے جسے تو بھی نہیں جانتا اور میں تجھے اس کا بدلہ دوں گا اور وہ ہے ذکر خفی یعنی آہستہ آواز سے ذکر کرنا۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Ya'la. Haythami (Vol.10 Pg.81) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں ہم نے جنت البقیع میں آگ کی روشنی دیکھی تو ہم وہاں گئے، دیکھا کہ حضورؐ قبر میں اترے ہوئے ہیں اور فرما رہے ہیں مجھے یہ آدمی دو۔ چنانچہ انہوں نے قبر کے پاؤں کی طرف سے وہ جنازہ دے دیا۔ میں نے دیکھا تو یہ وہ صحابی تھے جو اونچی آواز سے ذکر کیا کرتے تھے۔",""],[" (2)","s"]]]],"f":[["(2)","Abu Dawood, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.137). Abu Nu'aym has reported a similar narration in his Hilya (Vol.3 Pg.351)."]]},{"b":[["n",[["حضرت ابن اسحاقؒ","b"],[" کہتے ہیں مجھے حضرت محمد بن ابراہیم تیمیؒ نے یہ قصہ سنایا کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ قبیلہ مزینہ کے آدمی تھے اور وہ ذوالبجادین یعنی دو چادر والے کہلاتے تھے۔ وہ یتیم تھے اور اپنے چچا کی تربیت میں تھے اور وہ چچا ان کے ساتھ بہت اچھا سلوک کرتا تھا۔ ان کے چچا کو یہ خبر ملی کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ مسلمان ہو گئے ہیں۔ اس نے جو کچھ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کو دے رکھا تھا وہ سب ان سے چھین لیا اور انہیں بالکل ننگا کر کے نکال دیا۔ وہ اپنی والدہ کے پاس آئے تو اس نے اپنی ایک دھاری دار چادر کے دو ٹکڑے کر کے انہیں دیے۔ انہوں نے ایک ٹکڑے کو لنگی بنا کر باندھ لیا اور دوسرے کو اوڑھ لیا پھر وہ حضورؐ کی خدمت میں آ گئے۔ حضورؐ نے فرمایا آج سے تم عبد",""],["ٱللَّٰه","a"],[" ذوالبجادین ہو اور تم میرے دروازے پر پڑے رہو۔ چنانچہ وہ حضورؐ کے دروازے پر پڑ گئے اور وہ اونچی آواز سے ذکر کیا کرتے تھے۔ حضرت عمرؓ نے کہا کیا یہ ریا کار ہے؟ حضورؐ نے فرمایا نہیں، یہ تو آہیں بھر کر رونے والوں میں سے ایک ہے۔ حضرت تیمیؒ فرماتے ہیں حضرت ابن مسعودؓ بیان کیا کرتے تھے کہ میں غزوہ تبوک میں ایک دفعہ آدھی رات کو کھڑا ہوا تو میں نے لشکر کے ایک کونے میں آگ جلتی ہوئی دیکھی، میں وہاں گیا تو دیکھا حضورؐ اور حضرت ابوبکرؓ اور حضرت عمرؓ تشریف فرما ہیں اور حضرت عبد",""],["ٱللَّٰه","a"],[" ذوالبجادینؓ کا انتقال ہو چکا ہے اور لوگ ان کی قبر کھود چکے ہیں اور حضورؐ ان کی قبر میں اترے ہوئے ہیں۔ جب ہم انہیں دفن کر چکے تو حضورؐ نے فرمایا اے ",""],["ٱللَّٰه","a"],["! میں اس سے راضی ہوں تو بھی اس سے راضی ہو جا۔",""],[" (3)","s"]]]],"f":[["(3)","Isaabah (Vol.2 Pg.238). Baghawi, Ibn Mandah and Ahmad have all reported similar narrations."]]},{"b":[["n",[["حضرت عقبہ بن عامرؓ","b"],[" فرماتے ہیں ایک آدمی جنہیں ذوالبجادین کہا جاتا تھا ان کے بارے میں نبی کریمؐ نے فرمایا بے شک یہ آہیں بھر کر رونے والا ہے اور یہ اس وجہ سے فرمایا کہ وہ تلاوت قرآن، دعا اور ",""],["ٱللَّٰه","a"],[" کا ذکر کثرت سے اونچی آواز سے کیا کرتے تھے۔",""]]]],"f":[]}]},"116":{"lead":[],"stories":[{"b":[["n",[["حضرت صفیہؓ","b"],[" فرماتی ہیں حضورؐ میرے پاس تشریف لائے، میرے سامنے چار ہزار گٹھلیاں پڑی ہوئی تھیں جن پر میں سبحان ",""],["ٱللَّٰه","a"],[" پڑھ رہی تھی۔ حضورؐ نے فرمایا کیا میں تمہیں اس طرح سبحان ",""],["ٱللَّٰه","a"],[" پڑھنا نہ بتاؤں جو تمہارے اب تک کے سبحان ",""],["ٱللَّٰه","a"],[" پڑھنے کی مقدار سے زیادہ ہو؟ میں نے کہا ضرور بتائیں۔ فرمایا",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ خَلْقِهِ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" کی مخلوق کی تعداد کے برابر سبحان ",""],["ٱللَّٰه","a"],["۔\" حاکم کی روایت میں ہے",""]]],["q",[["سُبْحَانَ ٱللَّهِ عَدَدَ مَا خَلَقَ مِنْ شَىْءٍ","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" نے جو کچھ پیدا کیا ہے اس کے برابر سبحان ",""],["ٱللَّٰه","a"],["۔\" جامع اذکار کے عنوان میں بھی کچھ اذکار گزر چکے ہیں۔",""],[" (1)","s"],[" (2)","s"]]]],"f":[["(1)","Tirmidhi."],["(2)","Haakim, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.99)."]]},{"b":[["n",[["نبی کریمؐ کے آزاد کردہ غلام ",""],["حضرت ابوصفیہؓ","b"],[" کے بارے میں آتا ہے کہ ان کے سامنے چمڑے کا ایک بچھونا رکھا جاتا اور ایک ٹوکرا لایا جاتا جس میں کنکریاں ہوتیں تو وہ ان پر زوال تک سبحان ",""],["ٱللَّٰه","a"],[" پڑھتے رہتے، پھر اسے اٹھا لیا جاتا، پھر جب ظہر پڑھ لیتے تو پھر شام تک سبحان ",""],["ٱللَّٰه","a"],[" پڑھتے رہتے۔",""],[" (3)","s"]]]],"f":[["(3)","Baghawi, as quoted in Al Bidaayah wan Nihaayah (Vol.5 Pg.322)."]]},{"b":[["n",[["حضرت یونس بن عبیدؒ","b"],[" اپنی والدہ سے نقل کرتے ہیں وہ کہتی ہیں کہ میں نے مہاجرین کے ایک آدمی حضرت ابوصفیہؓ کو دیکھا کہ وہ گٹھلیوں پر تسبیح پڑھ رہے تھے۔",""],[" (4)","s"]]]],"f":[["(4)","Baghawi and Bukhaari (not in his Saheeh), as quoted in Isaabah (Vol.4 Pg.105). Ibn Sa'd (Vol.7 Pg.60) has reported a similar narration."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" کے پاس ایک دھاگہ تھا جس میں دو ہزار گرہیں لگی ہوئی تھیں، جب تک ان سب پر تسبیح نہ پڑھ لیتے اس وقت تک سویا نہ کرتے۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym in his Hilya (Vol.1 Pg.383)."]]},{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں مجھے قبیلہ طفاوہ کے ایک بڑے میاں نے اپنا قصہ سنایا۔ کہتے ہیں میں مدینہ میں حضرت ابوہریرہؓ کا مہمان بنا۔ میں نے نبی کریمؐ کا کوئی صحابی ان سے زیادہ عبادت میں محنت کرنے والا اور ان سے زیادہ مہمان کی خیر خبر لینے والا نہیں دیکھا۔ ایک دن میں ان کے پاس تھا اور وہ اپنے تخت پر تھے اور ان کے پاس ایک تھیلی تھی جس میں کنکریاں یا گٹھلیاں تھیں اور ان کے تخت کے نیچے ان کی ایک کالی باندی بیٹھی ہوئی تھی اور وہ ان کنکریوں پر تسبیح پڑھ رہے تھے۔ جب تھیلی کی تمام کنکریاں ختم ہو گئیں تو انہوں نے وہ تھیلی اس باندی کے سامنے ڈال دی۔ اس باندی نے وہ ساری کنکریاں اس تھیلی میں ڈال دیں اور تھیلی اٹھا کر پھر ان کے سامنے رکھ دی۔ آگے لمبی حدیث ذکر کی ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Dawood (Vol.3 Pg.55)."]]},{"b":[["n",[["حضرت حکیم بن دیلمیؒ","b"],[" کہتے ہیں حضرت سعدؓ کنکریوں پر سبحان ",""],["ٱللَّٰه","a"],[" پڑھا کرتے تھے۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Sa'd (Vol.3 Pg.143)."]]}]},"117":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عمرؓ","b"],[" نے فرمایا تم اس کی پوری کوشش کرو کہ ",""],["ٱللَّٰه","a"],[" کا ذکر صرف طہارت کی حالت میں کیا کرو۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.209)."]]},{"b":[["n",[["حضرت ابوعثمان نہدیؒ","b"],[" کہتے ہیں مجھے حضرت ابوہریرہؓ کی طرف سے یہ بات پہنچی کہ انہوں نے فرمایا کہ مجھے یہ حدیث پہنچی ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنے بندے کو ایک نیکی کے بدلے دس لاکھ نیکیاں دیتے ہیں۔ حضرت ابوہریرہؓ نے فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے بیس لاکھ نیکیاں دیں گے، پھر یہ آیت پڑھی",""]]],["q",[["يُضَٰعِفْهَا وَيُؤْتِ مِن لَّدُنْهُ أَجْرًا عَظِيمًا","a"]]],["p",[["ترجمہ: \"تو اس کو کئی گنا کر دیں گے اور اپنے پاس سے اجر عظیم دیں گے۔\" (سورت نساء آیت ۴۰) پھر حضرت ابوہریرہؓ نے فرمایا جب ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے اجر عظیم کہہ رہے ہیں تو اس کا اندازہ کون لگا سکتا ہے؟ ایک روایت میں یہ ہے کہ حضرت ابوعثمانؒ کہتے ہیں میں نے حضرت ابوہریرہؓ کی خدمت میں حاضر ہو کر عرض کیا کہ مجھے یہ بات پہنچی ہے کہ آپ فرماتے ہیں کہ نیکی کو دس لاکھ گنا بڑھایا جاتا ہے۔ انہوں نے فرمایا تمہیں اسی بات پر حیرانی ہو رہی ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے حضورؐ کو یہ فرماتے ہوئے سنا۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad and Bazzaar, as quoted in Majma'uz Zawaa'id (Vol.10 Pg.145)."]]}]}}});
